// PM 2026-06-15: si el valor guardado en DB es una URL (http(s):// o ruta
// absoluta /…) o un data: URI, lo devolvemos tal cual sin tocar — antes el
// lookup en IMG_BY_SLUG fallaba y devolvía IMG_PALM aunque la URL viniera
// completa desde Supabase. Sólo se resuelve por slug cuando el valor no
// parece una URL (back-compat con los pocos slugs internos legacy).
const resolveImg = (val) => {
  if (typeof val === "string" && /^(https?:\/\/|\/|data:)/.test(val)) return val;
  return IMG_BY_SLUG[val] || IMG_PALM;
};
const resolveImgs = (vals) => Array.isArray(vals) && vals.length ? vals.map(resolveImg) : [IMG_PALM];

// PM 2026-06-15: aplica el markup admin (% o cantidad en centavos) sobre el
// price_cents base. Devuelve el precio efectivo en CENTAVOS, redondeado a
// entero. Si type es null o value es null, devuelve el base sin cambios.
// El precio efectivo es lo que ve el cliente y lo que se usa para invoice;
// el base se conserva para auditoría y para que el admin pueda editar el
// markup sin perder la referencia original.
function applyMarkupCents(baseCents, type, value) {
  const base = Number(baseCents) || 0;
  if (!type || value == null || Number.isNaN(Number(value))) return base;
  const v = Number(value);
  if (type === "percent") return Math.max(0, Math.round(base * (1 + v / 100)));
  if (type === "amount") return Math.max(0, Math.round(base + v));
  return base;
}

function mapStayToHotel(s) {
  const imgs = Array.isArray(s.images) ? s.images : [];
  // PM 2026-06-15: precio efectivo = base + markup admin (porcentaje o cantidad).
  // Es lo que ve el cliente y lo que va al invoice — el markup no se desglosa.
  const effectiveCents = applyMarkupCents(s.price_cents, s.markup_type, s.markup_value);
  return {
    id: s.slug,
    dbId: s.id,
    // PM 2026-06-12: exponemos cada idioma por separado además del `name`
    // resuelto (preferencia ES → EN). Antes solo había `name` y el form de
    // edición tomaba ese valor para AMBOS tabs ES y EN, "perdiendo" lo que
    // se había guardado en cada idioma. Mismo tratamiento para descripción.
    name: s.title_es || s.title_en || s.slug,
    nameEN: s.title_en || "",
    nameES: s.title_es || "",
    zone: s.location || "",
    type: "Villa",
    // `price` = precio efectivo en USD (con markup aplicado). El público y
    // el invoice usan este valor. `basePrice` conserva el original para
    // que el admin pueda editar el markup sin perder la referencia.
    price: Math.round(effectiveCents / 100),
    basePrice: Math.round((s.price_cents || 0) / 100),
    markupType: s.markup_type || null,
    markupValue: s.markup_value == null ? null : Number(s.markup_value),
    rating: Number(s.rating_avg) || 0,
    reviews: s.rating_count || 0,
    sleeps: s.max_guests || 1,
    bedrooms: s.bedrooms || 0,
    bathrooms: s.bathrooms || 0,
    // PM 2026-06-23 (D): si no hay imagen real, devolvemos "" para que
    // MediaImg muestre SU placeholder elegante (icono + nombre del stay)
    // en lugar del IMG_PALM (sunset SVG genérico) que confundía al cliente
    // ("las imágenes no cargan"). El gallery sí mantiene el fallback para
    // no romper el carousel del detail page.
    img: imgs[0] ? resolveImg(imgs[0]) : "",
    gallery: resolveImgs(imgs),
    amenities: Array.isArray(s.amenities) ? s.amenities : [],
    desc: s.short_desc_es || s.short_desc_en || "",
    descEN: s.short_desc_en || "",
    descES: s.short_desc_es || "",
    // PM 2026-06-15: description_es/_en es el cuerpo largo (historia completa
    // del stay). Antes este contenido se guardaba solo en memoria (STAY_ABOUT)
    // → al recargar el detail page aparecía vacío. Ahora viene de DB.
    body: s.description_es || s.description_en || "",
    bodyES: s.description_es || "",
    bodyEN: s.description_en || "",
    color: s.featured ? "gold" : "sky",
    lat: Number(s.lat) || 0,
    lng: Number(s.lng) || 0,
    status: s.active ? "published" : "hidden",
    bookings: 0,
    rooms: s.bedrooms || 0,
    services: (s.amenities || []).length,
    checkIn: "15:00",
    checkOut: "11:00",
    partnerId: s.partner_id || null,
    partnerUrl: s.partner_url || "",
    // PM 2026-06-25: experiencia dinámica (FK).
    experienceId: s.experience_id || null,
    // Pricing mixto + categoría (PM 2026-06-10).
    pricingUnit: s.pricing_unit || "per_night",
    pricingExtras: Array.isArray(s.pricing_extras) ? s.pricing_extras : [],
    category: s.category || "",
    // Políticas editables (PM 2026-06-11): si el stay no las definió,
    // el detail page hace fallback al texto default.
    checkInTime: s.check_in_time || "3:00 PM",
    checkOutTime: s.check_out_time || "11:00 AM",
    cancellationPolicy: s.cancellation_policy || "",
    houseRules: s.house_rules || "",
  };
}

function mapTourToTour(t) {
  const imgs = Array.isArray(t.images) ? t.images : [];
  // PM 2026-06-15: ver mapStayToHotel — precio efectivo con markup admin.
  const effectiveCents = applyMarkupCents(t.price_cents, t.markup_type, t.markup_value);
  return {
    id: t.slug,
    dbId: t.id,
    name: t.title_es || t.title_en || t.slug,
    nameEN: t.title_en || "",
    nameES: t.title_es || "",
    day: "",
    duration: t.duration_minutes ? `${Math.round(t.duration_minutes / 60)} hours` : "",
    price: Math.round(effectiveCents / 100),
    basePrice: Math.round((t.price_cents || 0) / 100),
    markupType: t.markup_type || null,
    markupValue: t.markup_value == null ? null : Number(t.markup_value),
    rating: Number(t.rating_avg) || 0,
    reviews: t.rating_count || 0,
    capacity: t.max_pax || 1,
    difficulty: t.difficulty || "Easy",
    type: "beach",
    // PM 2026-06-23 (D): ver mapStayToHotel — "" cuando no hay imagen real
    // para que MediaImg use su placeholder elegante en vez del SVG IMG_PALM.
    img: imgs[0] ? resolveImg(imgs[0]) : "",
    gallery: resolveImgs(imgs),
    includes: Array.isArray(t.includes) ? t.includes : [],
    bring: [],
    itinerary: [],
    desc: t.short_desc_es || t.short_desc_en || "",
    descEN: t.short_desc_en || "",
    descES: t.short_desc_es || "",
    // PM 2026-06-15: ver mapStayToHotel — description_es/_en es el cuerpo
    // largo del tour, ahora se persiste/lee desde DB.
    body: t.description_es || t.description_en || "",
    bodyES: t.description_es || "",
    bodyEN: t.description_en || "",
    // PM 2026-06-15: meeting_point del DB. Antes no se exponía y la
    // sección "Punto de encuentro" del detail page quedaba sin data
    // aunque el admin lo cargara.
    meetingPoint: t.meeting_point || "",
    color: t.featured ? "gold" : "green",
    location: t.location || "",
    lat: Number(t.lat) || 0,
    lng: Number(t.lng) || 0,
    status: t.active ? "published" : "hidden",
    bookings: 0,
    partnerId: t.partner_id || null,
    partnerUrl: t.partner_url || "",
    // Pricing mixto + categoría (PM 2026-06-10).
    pricingUnit: t.pricing_unit || "per_person",
    pricingExtras: Array.isArray(t.pricing_extras) ? t.pricing_extras : [],
    // `category` legacy = texto libre tipo "Adventure / Cultural" (columna
    // tours.category). Distinto del experience_category nuevo (3 buckets).
    category: t.category || "",
    // PM 2026-06-22: clasificación nueva del review del cliente — agrupa los
    // tours del Home en 3 grandes experiencias (Beach Escape, River & Mountain,
    // UTV Tours in West Coast). Editable desde el admin.
    experienceCategory: t.experience_category || "",
    // PM 2026-06-25: experiences dinámicas. experience_id apunta a la
    // tabla `experiences`. Si la migración no fue aplicada todavía el
    // campo viene undefined y se ignora.
    experienceId: t.experience_id || null,
    partnerName: t.partner_name || "",
    markupPct: t.markup_pct == null ? 10 : Number(t.markup_pct),
  };
}

function mapVehicleToVehicle(v) {
  // El schema `vehicles` de Supabase tiene name, type, max_pax, max_luggage,
  // price_cents, active, features, description. plate/driver/trips/status
  // enum NO viven en DB — se rellenan con defaults sensatos para que la UI
  // legacy no crashee (.status.replace() en la tabla del admin requeria string).
  return {
    id: v.id, // UUID Supabase (necesario para admin CRUD update/delete)
    slug: (v.type || v.name || "").toLowerCase().replace(/\s+/g, "-"),
    name: v.name || "",
    type: v.type || "",
    seats: v.max_pax || 4,
    bags: v.max_luggage || 2,
    base: Math.round((v.price_cents || 0) / 100),
    // PM 2026-06-17: perKm desde DB (antes hardcoded 2.5 para todos los
    // vehículos). NULL = 0 (no se cobra por km, solo flat base).
    perKm: v.price_per_km_cents == null ? 0 : Number(v.price_per_km_cents) / 100,
    // PM 2026-06-17: desc + features ahora vienen de DB (antes hardcoded).
    desc: v.description || "",
    features: Array.isArray(v.features) ? v.features : [],
    active: v.active !== false,
    status: v.active === false ? "out_of_service" : "available",
    plate: "",
    driver: "",
    trips: 0,
  };
}

// PM 2026-06-23: helper compartido. Calcula el precio que se muestra al
// cliente público para UNA leg (from→to + km) usando UN vehículo, según
// el `pricing_mode` que el admin eligió para la ruta correspondiente.
//   - route_price       → base de la ruta tal cual (ignora vehículo+km)
//   - vehicle_formula   → vehículo.base + vehículo.perKm × km
//   - route_plus_vehicle → suma de los dos anteriores
// Si la leg no matchea ninguna ruta del admin (estimada), cae a
// vehicle_formula porque no tenemos un precio explícito que respetar.
function computeLegPrice({ route, vehicle, km }) {
  if (!vehicle) return 0;
  const base = vehicle.base || 0;
  const perKm = vehicle.perKm || 0;
  const formula = base + perKm * (Number(km) || 0);
  if (!route) return formula; // leg estimada, sin ruta admin
  const mode = route.pricingMode || "route_price";
  const routeOnly = route.price || 0;
  if (mode === "route_price") return routeOnly;
  if (mode === "route_plus_vehicle") return routeOnly + formula;
  // vehicle_formula
  return formula;
}

function mapRouteToRoute(r) {
  return {
    id: r.id,
    from: r.from_location,
    to: r.to_location,
    price: Math.round((r.base_price_cents || 0) / 100),
    priceCents: r.base_price_cents || 0,
    maxPax: r.max_pax || 4,
    distanceKm: r.distance_km == null ? null : Number(r.distance_km),
    durationMinutes: r.duration_minutes ?? null,
    km: Number(r.distance_km) || 0,
    time: r.duration_minutes ? `${Math.floor(r.duration_minutes / 60)}h ${r.duration_minutes % 60}min` : "",
    // `featured`: el admin marca una ruta como "popular" (promoción).
    // La sección Popular Routes del público filtra por este flag.
    featured: r.featured === true,
    active: r.active !== false,
    pricingUnit: r.pricing_unit || "per_unit",
    // PM 2026-06-11: vehicle FK opcional en DB pero requerido en UI nueva.
    vehicleId: r.vehicle_id || null,
    // PM 2026-06-23: descripción corta editable desde admin (visible en
    // Servicios → Popular Routes y en /transfer-results).
    descES: r.description_es || "",
    descEN: r.description_en || "",
    // pricing_mode: cómo se calcula el precio mostrado al cliente final.
    //   route_price        → usa solo route.priceCents
    //   vehicle_formula    → usa vehículo.base + vehículo.perKm × km
    //   route_plus_vehicle → suma ambos
    pricingMode: r.pricing_mode || "route_price",
  };
}

function mapPostToAdminPost(p) {
  // PM 2026-06-17: el EditModal lee nameEN/nameES (para los tabs ES/EN del
  // título) y excerpt/bodyES separados. El mapper antes hacía fallback
  // "es || en" lo que mezclaba idiomas: al abrir EDIT POST el campo TITLE
  // se cargaba vacío (porque el modal lee it.nameEN/it.name, no it.title) y
  // el cuerpo en EN traía el texto en ES si no había EN. Exponemos los
  // campos bilingues por separado + un alias `name` para el modal compartido.
  const titleEN = p.title_en || "";
  const titleES = p.title_es || "";
  return {
    // PM 2026-06-11: el id "lógico" es el slug (lo usa el front para
    // routing /post?slug=...). Pero las server actions de admin (toggle
    // featured/publish/delete) esperan el UUID real → lo exponemos como
    // dbId. Antes mandábamos el slug como id y el server respondía
    // "Identificador inválido".
    id: p.slug,
    dbId: p.id,
    title: titleES || titleEN || p.slug,
    // Alias para el EditModal compartido (lee it.name como base).
    name: titleEN || titleES || p.slug,
    nameEN: titleEN,
    nameES: titleES,
    slug: p.slug,
    category: p.category || "",
    author: "",
    date: (p.published_at || p.created_at || "").slice(0, 10),
    status: p.status,
    featured: !!p.featured,
    // PM 2026-06-23 (D): el campo `image` puede contener una URL real
    // (Supabase Storage, http(s), data: URI) o un IDENTIFICADOR legacy
    // tipo "IMG_MANGROVES" (assets inline definidos arriba en el módulo).
    // Antes pasábamos el string crudo a MediaImg y los identificadores
    // se intentaban cargar como URL → 404 → placeholder. Ahora resolvemos
    // identificadores al asset real.
    img: resolveImg(p.image || "IMG_PALM"),
    views: p.views || 0,
    // EN como base, ES separado — el modal los inicializa así.
    excerpt: p.excerpt_en || "",
    excerptES: p.excerpt_es || "",
    body: p.body_en || "",
    bodyES: p.body_es || "",
    // PM 2026-06-26: fecha programada de publicación. El modal de edit
    // pre-llena scheduleDate / scheduleTime con esto. publishAt (ISO) se
    // mantiene para mostrar badge "LIVE" cuando ya pasó la fecha.
    publishAt: p.publish_at || null,
    scheduleDate: p.publish_at ? p.publish_at.slice(0, 10) : "",
    scheduleTime: p.publish_at ? p.publish_at.slice(11, 16) : "09:00",
  };
}

