const SITE_SETTINGS = { ...SITE_SETTINGS_DEFAULTS };
function getSetting(key) {
  const v = SITE_SETTINGS[key];
  return v && String(v).trim().length > 0 ? v : SITE_SETTINGS_DEFAULTS[key] || "";
}

async function loadInitialData() {
  try {
    const [{ createClient }, { getStays, getTours, getTransferRoutes, getTransferLocations, getVehicles, getPublishedPosts, getPartners }, { getSiteSettings }] = await Promise.all([
      import("@/lib/supabase/client"),
      import("@/lib/queries/catalog"),
      import("@/lib/queries/settings"),
    ]);
    const sb = createClient();
    // PM 2026-06-11: pasamos `activeOnly: false` para traer también los stays
    // y tours INACTIVOS (oculto/borrador). El admin necesita verlos en su panel
    // para gestionarlos; las páginas públicas ya filtran por status del lado
    // del cliente (HomePage, /tours, /stays). Antes el conteo desplegaba 32
    // en vez de los 33 reales del DB porque uno estaba con active=false.
    // PM 2026-06-26: cada query tolerante a fallo. Si UNA rompía (ej.
    // posts con columna publish_at ausente porque la migración no se
    // aplicó), antes Promise.all rechazaba completo y el sitio quedaba
    // en BLANCO. Ahora cada query devuelve [] si falla y el resto del
    // catálogo sigue funcionando.
    const safe = (label, p) => p.catch((e) => {
      console.warn(`[loadInitialData] ${label} fail:`, e?.message || e);
      return [];
    });
    const [stays, tours, routes, locations, vehicles, posts, partners, settings, experiences, postCategories] = await Promise.all([
      safe("getStays", getStays(sb, { activeOnly: false })),
      safe("getTours", getTours(sb, { activeOnly: false })),
      // PM 2026-06-12: rutas inactivas también se cargan para que el admin
      // las pueda gestionar (toggle, edición). Las páginas públicas filtran
      // por r.active del lado del cliente.
      safe("getTransferRoutes", getTransferRoutes(sb, { activeOnly: false })),
      safe("getTransferLocations", getTransferLocations(sb)),
      safe("getVehicles", getVehicles(sb)),
      safe("getPublishedPosts", getPublishedPosts(sb, {})),
      safe("getPartners", getPartners(sb, { activeOnly: false })),
      getSiteSettings(sb).catch((e) => { console.warn("[loadInitialData] getSiteSettings fail:", e?.message); return {}; }),
      // PM 2026-06-25: experiencias dinámicas. server action es tolerante:
      // si la tabla no existe (migración pendiente), devuelve [].
      sbListExperiences().catch(() => []),
      // PM 2026-06-26: categorías de posts dinámicas (mismo patrón).
      sbListPostCategories().catch(() => []),
    ]);
    void sb; // Drivers se cargan en AdminPanel via Server Action listDrivers
             // (requiere staff auth) — no se pre-carga en loadInitialData
             // porque el catálogo público no necesita drivers.

    // PM 2026-06-26: cada bloque defensivo independiente. Si un mapper
    // crashea (shape inesperada de DB, migración pendiente, etc.), no
    // aborta los siguientes. Antes, un solo crash silencioso dejaba el
    // 80% de los catálogos vacíos.
    const safePopulate = (label, arr, source, mapper) => {
      try {
        arr.length = 0;
        (source || []).forEach((x) => arr.push(mapper ? mapper(x) : x));
      } catch (e) {
        console.error(`[loadInitialData] crash poblando ${label}:`, e);
      }
    };
    safePopulate("HOTELS", HOTELS, stays, mapStayToHotel);
    safePopulate("TOURS", TOURS, tours, mapTourToTour);
    safePopulate("VEHICLES", VEHICLES, vehicles, mapVehicleToVehicle);
    safePopulate("ROUTES", ROUTES, routes, mapRouteToRoute);
    safePopulate("TRANSFER_LOCATIONS", TRANSFER_LOCATIONS, locations, null);
    safePopulate("A_POSTS", A_POSTS, posts, mapPostToAdminPost);
    safePopulate("PARTNERS", PARTNERS, partners, null);
    safePopulate("EXPERIENCES", EXPERIENCES, experiences, null);
    safePopulate("POST_CATEGORIES", POST_CATEGORIES, postCategories, null);

    // Mergear settings de DB sobre defaults — keys no presentes mantienen
    // el default. Cualquier value vacío también cae al default vía getSetting.
    Object.assign(SITE_SETTINGS, settings || {});
    // PM 2026-06-26: flag para que el polling del AdminPanel sepa cuándo
    // TODOS los globals están listos. Antes leía TOURS.length>0 y a veces
    // se gatillaba con solo TOURS poblado mientras PARTNERS/EXPERIENCES
    // aún no — los setters locales se llamaban con [].
    if (typeof window !== "undefined") window.__PRDISE_DATA_READY = true;
    return true;
  } catch (e) {
    console.error("loadInitialData error:", e);
    return false;
  }
}

const PRDISE = {
  save: (k, v) => { try { localStorage.setItem("prdise_" + k, JSON.stringify(v)); return true; } catch { return false; } },
  load: (k, d = null) => { try { const v = localStorage.getItem("prdise_" + k); return v ? JSON.parse(v) : d; } catch { return d; } },
  del: (k) => { try { localStorage.removeItem("prdise_" + k); } catch {} },
  genRef: (p) => p + "-" + Date.now().toString(36).toUpperCase() + Math.random().toString(36).substr(2, 4).toUpperCase(),
};
const fmt = (n) => "$" + Number(n).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ",");

// PM 2026-06-17: label de unidad de precio según pricing_unit del servicio.
// Antes las cards hardcodeaban "/ person" y "/ night" → cuando un servicio
// estaba configurado como per_unit (fijo por servicio/evento) el cliente
// veía "$X / person" engañosamente. Caso reportado: WATER BIRTHDAY SPLASH
// (per_unit) mostraba "$2130 / person" en su card.
function pricingUnitLabel(unit, lang) {
  const map = {
    es: { per_night: "/ noche", per_person: "/ persona", per_hour: "/ hora", per_unit: "/ servicio", per_attraction: "/ atracción" },
    en: { per_night: "/ night", per_person: "/ person", per_hour: "/ hour", per_unit: "/ service", per_attraction: "/ attraction" },
  };
  const table = lang === "es" ? map.es : map.en;
  return table[unit] || (lang === "es" ? "/ servicio" : "/ service");
}

// CSV export utility (PM 2026-06-11). Cualquier sección del admin que tenga
// botón "Exportar" puede invocarlo con un array de objetos plano. Genera un
// CSV con BOM UTF-8 (para que Excel respete acentos), encabezados derivados
// de las keys del primer objeto y disparado vía link de descarga temporal.
function downloadCsv(filename, rows) {
  if (!Array.isArray(rows) || rows.length === 0) {
    alert("No hay datos para exportar.");
    return;
  }
  const headers = Object.keys(rows[0]);
  const escape = (v) => {
    if (v == null) return "";
    const s = String(v);
    return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };
  const csv = [
    headers.join(","),
    ...rows.map((r) => headers.map((h) => escape(r[h])).join(",")),
  ].join("\n");
  const blob = new Blob(["﻿" + csv], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
const toISO = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;

