function ContactPage() {
  const { t, lang } = useLang();
  const [form, setForm] = useState({ name: "", email: "", phone: "", subject: "General Inquiry", message: "" });
  const [sent, setSent] = useState(false);
  const submit = async () => {
    if (!form.name || !form.email || !form.message) {
      alert(lang==="es"?"Completá los campos requeridos":"Please complete the required fields");
      return;
    }
    try {
      const fd = new FormData();
      fd.append("name", form.name);
      fd.append("email", form.email);
      if (form.phone) fd.append("phone", form.phone);
      fd.append("message", `[${form.subject}] ${form.message}`);
      const res = await sbSubmitContact(fd);
      if (!res?.ok) {
        alert((lang==="es"?"No se pudo enviar el mensaje: ":"Could not send the message: ") + (res?.error || (lang==="es"?"error desconocido":"unknown error")));
        return;
      }
    } catch (e) {
      alert((lang==="es"?"Error al enviar el mensaje: ":"Error sending the message: ") + (e?.message || e));
      return;
    }
    setSent(true);
    setTimeout(() => { setSent(false); setForm({ name: "", email: "", phone: "", subject: "General Inquiry", message: "" }); }, 4000);
  };
  return (
    <>
      <PageHero tag={t("contact")} title={t("contactTag")} titleEm="" subtitle={t("contactHeroSub")} />
      <div className="inner-page">
        <div className="inner-wrap">
          <div style={{ display: "grid", gridTemplateColumns: "1fr", gap: 28 }} className="layout-2col">
            <div className="step-card">
              <h2 style={{ fontFamily: "Bebas Neue", fontSize: 26, letterSpacing: ".04em", marginBottom: 6 }}>{t("sendMessage").toUpperCase()}</h2>
              <p style={{ fontSize: 13, color: "rgba(255,255,255,.5)", marginBottom: 10 }}>{t("letsChat")}</p>
              {/* PM 2026-06-22 (B): aviso del medio de respuesta. Editable
                  desde admin → Settings → Mensajes. */}
              <p style={{ fontSize: 12, color: "rgba(245,166,35,.85)", marginBottom: 20, padding: "8px 12px", borderRadius: 8, background: "rgba(245,166,35,.06)", border: "1px solid rgba(245,166,35,.18)", display: "flex", alignItems: "flex-start", gap: 8, lineHeight: 1.55 }}>
                <Mail style={{ width: 13, height: 13, marginTop: 2, flexShrink: 0 }} />
                <span>{getSetting(lang === "es" ? "contact_form_notice_es" : "contact_form_notice_en")}</span>
              </p>
              {sent ? (
                <div style={{ padding: 28, borderRadius: 16, background: "rgba(141,198,63,.1)", border: "1px solid rgba(141,198,63,.3)", textAlign: "center" }}>
                  <div style={{ width: 50, height: 50, borderRadius: "50%", background: "var(--green)", margin: "0 auto 14px", display: "flex", alignItems: "center", justifyContent: "center" }}><Check style={{ color: "#fff", strokeWidth: 3 }} /></div>
                  <h3 style={{ fontFamily: "Bebas Neue", fontSize: 22, color: "var(--green)" }}>{lang==="es"?"¡MENSAJE ENVIADO!":"MESSAGE SENT!"}</h3>
                  <p style={{ fontSize: 13, color: "rgba(255,255,255,.6)" }}>{lang==="es"?"Te responderemos en breve.":"We'll get back to you shortly."}</p>
                </div>
              ) : (
                <>
                  <div className="f-row">
                    <div><label className="f-lab">{t("yourName")} *</label><input className="f-in" value={form.name} onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))} /></div>
                    <div><label className="f-lab">{t("email")} *</label><input type="email" className="f-in" value={form.email} onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))} /></div>
                  </div>
                  <div className="f-row">
                    <div><label className="f-lab">{t("phone")}</label><input type="tel" className="f-in" value={form.phone} onChange={(e) => setForm((f) => ({ ...f, phone: e.target.value }))} /></div>
                    <div><label className="f-lab">{t("subject")}</label><select className="f-in" value={form.subject} onChange={(e) => setForm((f) => ({ ...f, subject: e.target.value }))}>
                      {/* Valor estable en EN para que el backend siempre
                          reciba el mismo key; el label visible se
                          localiza vía t(). Así el cambio de idioma no
                          rompe el value persistido en form.subject. */}
                      <option value="General Inquiry">{t("subjGeneral")}</option>
                      <option value="Tour Booking">{t("subjTour")}</option>
                      <option value="Stay Booking">{t("subjStay")}</option>
                      <option value="Transfer Request">{t("subjTransfer")}</option>
                      <option value="Custom Package">{t("subjCustom")}</option>
                    </select></div>
                  </div>
                  <div className="f-grp">
                    <label className="f-lab">{t("message")} *</label>
                    <textarea className="f-in" value={form.message} onChange={(e) => setForm((f) => ({ ...f, message: e.target.value }))} placeholder="..." />
                  </div>
                  <button type="button" onClick={submit} className="f-submit"><Send />{t("sendMessage")}</button>
                </>
              )}
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
              {[
                { Icon: Phone, label: lang==="es"?"Teléfono":"Phone", value: getSetting("contact_phone"), href: `tel:${getSetting("contact_phone_tel")}`, c: "gold" },
                { Icon: Mail, label: lang==="es"?"Correo":"Email", value: getSetting("contact_email"), href: `mailto:${getSetting("contact_email")}`, c: "orange" },
                { Icon: MapPin, label: lang==="es"?"Ubicación":"Location", value: "Cabo Rojo, Puerto Rico", href: null, c: "green" },
                { Icon: MessageCircle, label: "WhatsApp", value: lang==="es"?"Chatea con nosotros":"Chat with us", href: `https://wa.me/${getSetting("whatsapp_phone")}`, c: "sky" },
              ].map((c, i) => (
                <a key={i} href={c.href || "#"} target={c.href?.startsWith("http") ? "_blank" : undefined} rel="noreferrer" style={{ display: "flex", alignItems: "center", gap: 14, padding: 18, borderRadius: 16, background: "rgba(255,255,255,.04)", border: "1px solid rgba(255,255,255,.06)" }}>
                  <div style={{ width: 44, height: 44, borderRadius: 14, background: COLORS[c.c] + "22", color: COLORS[c.c], display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                    <c.Icon style={{ width: 20, height: 20 }} />
                  </div>
                  <div>
                    <div style={{ fontSize: 10, fontWeight: 800, letterSpacing: ".14em", textTransform: "uppercase", color: "rgba(255,255,255,.4)", marginBottom: 2 }}>{c.label}</div>
                    <div style={{ fontSize: 14, fontWeight: 600 }}>{c.value}</div>
                  </div>
                </a>
              ))}
            </div>
          </div>
        </div>
      </div>
    </>
  );
}

