/* ═══════════════ ADMIN LOGIN PAGE ═══════════════ */
function LoginPage() {
  const { t, lang } = useLang();
  const [form, setForm] = useState({ email: "", password: "" });
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [reactivatePrompt, setReactivatePrompt] = useState(false);

  useEffect(() => {
    document.title = "Sign In — Living in PRDISE";
    const sess = PRDISE.load("session", null);
    if (sess) {
      if (sess.role === "admin") nav("/admin");
      else nav("/account");
    }
  }, []);

  const handleLogin = async () => {
    setError("");
    if (!form.email.trim() || !form.password.trim()) {
      setError(lang === "es" ? "Ingresa correo y contraseña" : "Please enter email and password");
      return;
    }
    setLoading(true);
    try {
      const fd = new FormData();
      fd.append("email", form.email.trim().toLowerCase());
      fd.append("password", form.password);
      const result = await sbSignIn(fd);
      if (!result?.ok) {
        if (result && "needsReactivation" in result) {
          setReactivatePrompt(true);
          setLoading(false);
          return;
        }
        setError(result?.error || "Credenciales inválidas");
        setLoading(false);
        return;
      }
      // Navegacion por path (no hash) para forzar un full page reload
      // que aplique las cookies recien seteadas por el Server Action. Si
      // solo cambiaramos el hash (#/admin), el browser no recarga y el
      // cliente Supabase de AdminPanelRoute no encuentra la sesion ->
      // getUser() retorna null -> rebote al login.
      // Los stubs /admin y /account redirigen al hash route correspondiente.
      const isStaff = result.role === "admin";
      window.location.assign(isStaff ? "/admin" : "/account");
    } catch (e) {
      setError(lang === "es" ? "Error inesperado, intenta de nuevo" : "Unexpected error, try again");
      setLoading(false);
    }
  };

  const handleReactivate = async () => {
    const result = await sbReactivateAccount();
    if (result.ok) {
      setReactivatePrompt(false);
      window.location.assign("/");
    } else {
      setError(result.error);
      setReactivatePrompt(false);
      await sbSignOut().catch(() => {});
    }
  };

  return (
    <div style={{ minHeight: "100vh", background: "linear-gradient(135deg,var(--deep),var(--ink))", display: "flex", alignItems: "center", justifyContent: "center", padding: 20, paddingTop: 100 }}>
      <div style={{ maxWidth: 440, width: "100%", background: "rgba(255,255,255,.04)", border: "1px solid rgba(255,255,255,.08)", borderRadius: 24, padding: "40px 32px", position: "relative", overflow: "hidden" }}>
        <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 4, background: "linear-gradient(90deg,var(--gold),var(--orange),var(--green),var(--sky))" }} />
        <div style={{ textAlign: "center", marginBottom: 28 }}>
          <div style={{ width: 64, height: 64, borderRadius: 18, background: "linear-gradient(135deg,var(--gold),var(--orange))", margin: "0 auto 18px", display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 12px 32px rgba(239,108,43,.3)" }}>
            <Lock style={{ width: 28, height: 28, color: "#fff" }} />
          </div>
          <h1 style={{ fontFamily: "Bebas Neue", fontSize: 32, letterSpacing: ".04em", marginBottom: 6 }}>{t("loginTitle")}</h1>
          <p style={{ fontSize: 13, color: "rgba(255,255,255,.6)" }}>{t("loginSub")}</p>
        </div>

        <div className="f-grp">
          <label className="f-lab">{t("email")}</label>
          <input
            type="email"
            className="f-in"
            placeholder="your@email.com"
            value={form.email}
            onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))}
            onKeyDown={(e) => e.key === "Enter" && document.getElementById("login-pwd")?.focus()}
          />
        </div>
        <div className="f-grp">
          <label className="f-lab">{t("password")}</label>
          <input
            id="login-pwd"
            type="password"
            className="f-in"
            placeholder="••••••••"
            value={form.password}
            onChange={(e) => setForm((f) => ({ ...f, password: e.target.value }))}
            onKeyDown={(e) => e.key === "Enter" && handleLogin()}
          />
        </div>

        {error && (
          <div style={{ padding: 12, borderRadius: 10, background: "rgba(248,113,113,.1)", border: "1px solid rgba(248,113,113,.3)", color: "#f87171", fontSize: 12.5, marginBottom: 14, display: "flex", alignItems: "center", gap: 8 }}>
            <AlertTriangle style={{ width: 14, height: 14, flexShrink: 0 }} />
            <span>{error}</span>
          </div>
        )}

        <button type="button" onClick={handleLogin} disabled={loading} className="f-submit">
          {loading ? "..." : <><Lock style={{ width: 14, height: 14 }} />{t("signIn")}</>}
        </button>

        <div style={{ textAlign: "center", marginTop: 12 }}>
          <NavLink to="/forgot-password" style={{ fontFamily: "Dancing Script, cursive", fontSize: 15, color: "rgba(255,255,255,.55)", textDecoration: "underline", textUnderlineOffset: 3 }}>
            {t("forgotPwd")}
          </NavLink>
        </div>

        <div style={{ display: "flex", alignItems: "center", gap: 10, margin: "22px 0 18px" }}>
          <div style={{ flex: 1, height: 1, background: "rgba(255,255,255,.08)" }} />
          <span style={{ fontSize: 10, fontWeight: 800, letterSpacing: ".16em", textTransform: "uppercase", color: "rgba(255,255,255,.35)" }}>{t("newHere")}</span>
          <div style={{ flex: 1, height: 1, background: "rgba(255,255,255,.08)" }} />
        </div>

        <NavLink to="/register" style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8, width: "100%", padding: "13px 0", borderRadius: 12, background: "transparent", border: "1.5px solid rgba(245,166,35,.4)", color: "#F5A623", fontSize: 13, fontWeight: 700, letterSpacing: ".12em", textTransform: "uppercase", transition: "all .25s", boxSizing: "border-box" }}>
          <User style={{ width: 14, height: 14 }} />{t("createAccount")}
        </NavLink>

        <div style={{ textAlign: "center", marginTop: 20 }}>
          <NavLink to="/" style={{ fontSize: 12, color: "rgba(255,255,255,.5)" }}>{t("backToSite")}</NavLink>
        </div>
      </div>
    </div>
  );
}

/* ═══════════════ REGISTER ═══════════════ */
function RegisterPage() {
  const { t, lang } = useLang();
  const [form, setForm] = useState({ firstName: "", lastName: "", email: "", phone: "", birthDate: "", password: "", confirmPassword: "", country: "", acceptTerms: false, acceptPrivacy: false });
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [showPwd, setShowPwd] = useState(false);
  const [showPwdConfirm, setShowPwdConfirm] = useState(false);
  const [otp, setOtp] = useState("");
  const [otpError, setOtpError] = useState("");
  const [otpLoading, setOtpLoading] = useState(false);
  const [otpVerified, setOtpVerified] = useState(false);
  const [resendCooldown, setResendCooldown] = useState(0);
  useEffect(() => {
    if (resendCooldown <= 0) return;
    const id = setTimeout(() => setResendCooldown((s) => s - 1), 1000);
    return () => clearTimeout(id);
  }, [resendCooldown]);
  const handleVerifyOtp = async () => {
    setOtpError("");
    if (!/^\d{6}$/.test(otp)) { setOtpError("El código debe tener 6 dígitos"); return; }
    setOtpLoading(true);
    const fd = new FormData();
    fd.append("email", form.email.trim().toLowerCase());
    fd.append("token", otp);
    const res = await sbVerifyEmailOtp(fd);
    setOtpLoading(false);
    if (res?.ok) {
      // PM 2026-06-17: el cliente ya eligió password en el formulario de
      // signup — verifyOtp deja una sesión transitoria con amr=[otp], lo que
      // dispararía el banner "Sesión temporal vía link" del MagicLinkPasswordPrompt.
      // Marcamos la flag para suprimirlo: no es una sesión sin password.
      try { sessionStorage.setItem("prdise_pwd_changed", "1"); } catch {}
      setOtpVerified(true);
      setTimeout(() => { window.location.hash = "#/login"; }, 1800);
    }
    else setOtpError(res?.error || "No se pudo verificar el código");
  };
  const handleResendOtp = async () => {
    if (resendCooldown > 0) return;
    setOtpError("");
    const fd = new FormData();
    fd.append("email", form.email.trim().toLowerCase());
    const res = await sbResendSignupOtp(fd);
    if (res?.ok) setResendCooldown(60);
    else setOtpError(res?.error || "No se pudo reenviar el código");
  };

  useEffect(() => {
    document.title = "Create Account — Living in PRDISE";
    // Solo redirigir si AuthBridge ya validó contra Supabase real (no localStorage residual).
    // Si hay sesión legítima, AuthBridge la habrá conservado; si no, ya la limpió.
    const sess = PRDISE.load("session", null);
    if (sess && sess.email) {
      if (sess.role === "admin") nav("/admin");
      else nav("/account");
    }
  }, []);

  // Live validation
  // Regex estricto: el local-part permite alfanuméricos + . _ + -; el dominio
  // permite solo alfanuméricos y guiones por etiqueta, con al menos un punto
  // y un TLD de 2+ letras. Esto descarta entradas como "user@gmail+x.com"
  // que el regex laxo anterior aceptaba pero Supabase Auth rechaza.
  const EMAIL_RE = /^[a-zA-Z0-9._+-]+@[a-zA-Z0-9-]+(\.[a-zA-Z0-9-]+)*\.[a-zA-Z]{2,}$/;
  const emailValid = form.email === "" || EMAIL_RE.test(form.email);
  const passwordsMatch = form.confirmPassword === "" || form.password === form.confirmPassword;

  // Password strength
  const pwdStrength = useMemo(() => {
    const p = form.password;
    if (!p) return { score: 0, label: "", color: "rgba(255,255,255,.15)" };
    let score = 0;
    if (p.length >= 8) score++;
    if (p.length >= 12) score++;
    if (/[a-z]/.test(p) && /[A-Z]/.test(p)) score++;
    if (/\d/.test(p)) score++;
    if (/[^a-zA-Z0-9]/.test(p)) score++;
    const meta = lang === "es" ? [
      { label: "Muy débil", color: "#EF4444" },
      { label: "Débil", color: "#EF6C2B" },
      { label: "Aceptable", color: "#F5A623" },
      { label: "Buena", color: "#8DC63F" },
      { label: "Fuerte", color: "#22C55E" },
      { label: "Muy fuerte", color: "#10B981" },
    ] : [
      { label: "Very weak", color: "#EF4444" },
      { label: "Weak", color: "#EF6C2B" },
      { label: "Fair", color: "#F5A623" },
      { label: "Good", color: "#8DC63F" },
      { label: "Strong", color: "#22C55E" },
      { label: "Very strong", color: "#10B981" },
    ];
    return { score, ...meta[Math.min(score, 5)] };
  }, [form.password, lang]);

  const handleRegister = async () => {
    setError("");
    if (!form.firstName.trim() || !form.lastName.trim()) { setError(lang === "es" ? "Ingresa nombre y apellido." : "Please enter your first and last name."); return; }
    if (!emailValid || !form.email) { setError(lang === "es" ? "Ingresa un email válido." : "Please enter a valid email address."); return; }
    if (!form.phone.trim() || form.phone.trim().length < 7) { setError(lang === "es" ? "Ingresa tu número de WhatsApp (con código de país, ej. +1 787 555 1234)." : "Please enter your WhatsApp number (with country code, e.g. +1 787 555 1234)."); return; }
    if (!form.birthDate) { setError(lang === "es" ? "Ingresá tu fecha de nacimiento." : "Please enter your date of birth."); return; }
    // Validar mínimo 13 años (política conservadora; ajustá si el negocio
    // requiere mayoría de edad: 18).
    if (form.birthDate) {
      const dob = new Date(form.birthDate);
      const now = new Date();
      const ageMs = now - dob;
      const ageYears = ageMs / (1000 * 60 * 60 * 24 * 365.25);
      if (Number.isNaN(ageYears) || ageYears < 13 || ageYears > 120) {
        setError(lang === "es" ? "La fecha de nacimiento no es válida." : "The date of birth is not valid.");
        return;
      }
    }
    if (!form.password || form.password.length < 8) { setError(lang === "es" ? "La contraseña debe tener al menos 8 caracteres." : "Password must be at least 8 characters long."); return; }
    if (form.password !== form.confirmPassword) { setError(lang === "es" ? "Las contraseñas no coinciden." : "Passwords do not match."); return; }
    if (!form.acceptTerms) { setError(lang === "es" ? "Debes aceptar los Términos y Condiciones." : "You must accept the Terms & Conditions."); return; }
    if (!form.acceptPrivacy) { setError(lang === "es" ? "Debes aceptar la Política de Privacidad." : "You must accept the Privacy Policy."); return; }

    setLoading(true);
    const fd = new FormData();
    fd.append("email", form.email.trim().toLowerCase());
    fd.append("password", form.password);
    fd.append("firstName", form.firstName.trim());
    fd.append("lastName", form.lastName.trim());
    fd.append("phone", form.phone.trim());
    if (form.birthDate) fd.append("birthDate", form.birthDate);
    const result = await sbSignUp(fd);
    setLoading(false);
    if (result.ok) {
      setSuccess(true);
    } else {
      setError(result.error);
    }
  };

  // PM 2026-06-18: OAuth (Google/Facebook/Apple) fuera de alcance — handler,
  // iconos SVG y CTAs sociales removidos para que la pantalla solo refleje
  // lo que el sistema realmente soporta (email + contraseña).

  if (success) {
    if (otpVerified) {
      return (
        <div style={{ minHeight: "100vh", background: "linear-gradient(135deg,var(--deep),var(--ink))", display: "flex", alignItems: "center", justifyContent: "center", padding: 20, paddingTop: 100 }}>
          <div style={{ maxWidth: 440, width: "100%", background: "rgba(255,255,255,.04)", border: "1px solid rgba(141,198,63,.3)", borderRadius: 24, padding: "48px 32px", textAlign: "center", position: "relative", overflow: "hidden" }}>
            <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 4, background: "linear-gradient(90deg,#8DC63F,#22C55E,#10B981)" }} />
            <div style={{ width: 76, height: 76, borderRadius: 20, background: "linear-gradient(135deg,#8DC63F,#22C55E)", margin: "0 auto 20px", display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 12px 36px rgba(141,198,63,.35)" }}>
              <CheckCircle style={{ width: 38, height: 38, color: "#fff" }} />
            </div>
            <h1 style={{ fontFamily: "Bebas Neue", fontSize: 30, letterSpacing: ".04em", marginBottom: 10, color: "#fff" }}>{lang==="es"?"¡CUENTA ACTIVADA!":"ACCOUNT ACTIVATED!"}</h1>
            <p style={{ fontSize: 14, color: "rgba(255,255,255,.75)", lineHeight: 1.6, marginBottom: 8 }}>{lang==="es"?"Tu correo fue confirmado correctamente.":"Your email was confirmed successfully."}</p>
            <p style={{ fontFamily: "Dancing Script, cursive", fontSize: 22, color: "var(--gold)", marginBottom: 20 }}>Welcome to Living in Paradise.</p>
            <div style={{ fontSize: 12, color: "rgba(255,255,255,.4)" }}>{lang==="es"?"Redirigiendo al login…":"Redirecting to sign in…"}</div>
          </div>
        </div>
      );
    }
    return (
      <div style={{ minHeight: "100vh", background: "linear-gradient(135deg,var(--deep),var(--ink))", display: "flex", alignItems: "center", justifyContent: "center", padding: 20, paddingTop: 100, paddingBottom: 40 }}>
        <div style={{ maxWidth: 460, width: "100%", background: "rgba(255,255,255,.04)", border: "1px solid rgba(245,166,35,.25)", borderRadius: 24, padding: "40px 32px", textAlign: "center", position: "relative", overflow: "hidden" }}>
          <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 4, background: "linear-gradient(90deg,var(--gold),var(--orange),var(--green),var(--sky))" }} />
          <div style={{ width: 64, height: 64, borderRadius: 18, background: "linear-gradient(135deg,var(--gold),var(--orange))", margin: "0 auto 16px", display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 12px 32px rgba(239,108,43,.3)" }}>
            <Lock style={{ width: 28, height: 28, color: "#fff" }} />
          </div>
          <h1 style={{ fontFamily: "Bebas Neue", fontSize: 28, letterSpacing: ".04em", marginBottom: 10, color: "#fff" }}>{lang==="es"?"CONFIRMA TU CORREO":"CONFIRM YOUR EMAIL"}</h1>
          <p style={{ fontSize: 14, color: "rgba(255,255,255,.75)", lineHeight: 1.6, marginBottom: 6 }}>{lang==="es"?"Te enviamos un código de 6 dígitos a:":"We sent a 6-digit code to:"}</p>
          <p style={{ fontSize: 14, color: "var(--gold)", fontWeight: 700, marginBottom: 22, wordBreak: "break-all" }}>{form.email}</p>
          <input
            type="text"
            inputMode="numeric"
            autoComplete="one-time-code"
            maxLength={6}
            value={otp}
            onChange={(e) => setOtp(e.target.value.replace(/\D/g, "").slice(0, 6))}
            onKeyDown={(e) => { if (e.key === "Enter" && !otpLoading) handleVerifyOtp(); }}
            placeholder="000000"
            style={{ width: "100%", padding: "16px 0", textAlign: "center", fontSize: 28, fontFamily: "monospace", letterSpacing: ".5em", background: "rgba(255,255,255,.05)", border: `1.5px solid ${otpError ? "rgba(239,68,68,.5)" : "rgba(245,166,35,.3)"}`, borderRadius: 14, color: "#fff", outline: "none", marginBottom: 12 }}
          />
          {otpError && (
            <div style={{ fontSize: 12, color: "#EF4444", marginBottom: 12, padding: "8px 12px", background: "rgba(239,68,68,.08)", border: "1px solid rgba(239,68,68,.2)", borderRadius: 8 }}>
              {otpError}
            </div>
          )}
          <button
            type="button"
            onClick={handleVerifyOtp}
            disabled={otpLoading || otp.length !== 6}
            style={{ width: "100%", padding: "14px 0", borderRadius: 99, background: otp.length === 6 && !otpLoading ? "linear-gradient(135deg,var(--gold),var(--orange))" : "rgba(255,255,255,.08)", color: "#fff", border: "none", fontWeight: 800, fontSize: 13, letterSpacing: ".12em", textTransform: "uppercase", cursor: otp.length === 6 && !otpLoading ? "pointer" : "not-allowed", marginBottom: 16, boxShadow: otp.length === 6 && !otpLoading ? "0 8px 24px rgba(239,108,43,.3)" : "none" }}
          >
            {otpLoading ? "Verificando..." : "Confirmar cuenta"}
          </button>
          <div style={{ fontSize: 12, color: "rgba(255,255,255,.5)", marginBottom: 8 }}>
            ¿No te llegó el código? Revisa spam o
            {" "}
            <button type="button" onClick={handleResendOtp} disabled={resendCooldown > 0}
              style={{ background: "none", border: "none", color: resendCooldown > 0 ? "rgba(255,255,255,.3)" : "var(--gold)", textDecoration: resendCooldown > 0 ? "none" : "underline", cursor: resendCooldown > 0 ? "default" : "pointer", padding: 0, font: "inherit" }}>
              {resendCooldown > 0 ? `reenviar en ${resendCooldown}s` : "reenviar"}
            </button>
          </div>
          <button type="button" onClick={() => { setSuccess(false); window.location.hash = "#/login"; }}
            style={{ display: "inline-flex", alignItems: "center", gap: 6, marginTop: 6, padding: "8px 14px", borderRadius: 10, background: "rgba(255,255,255,.06)", border: "1px solid rgba(255,255,255,.12)", color: "rgba(255,255,255,.85)", fontSize: 12, fontWeight: 600, cursor: "pointer", textDecoration: "none" }}>
            <ArrowRight style={{ width: 12, height: 12 }} />
            {lang === "es" ? "Ya confirmé, ir a iniciar sesión" : "Already confirmed, go to sign in"}
          </button>
          {/* PM 2026-06-17: salida de emergencia — si el cliente ve que tipeó
              mal el email (típico "yaho.com" vs "yahoo.com") puede volver al
              form sin perder lo demás. setSuccess(false) re-renderiza el form;
              el state de los campos sigue en memoria (no se reseteó). */}
          <div style={{ marginTop: 10 }}>
            <button type="button" onClick={() => { setSuccess(false); setOtp(""); setOtpError(""); }}
              style={{ display: "inline-flex", alignItems: "center", gap: 6, padding: "8px 14px", borderRadius: 10, background: "transparent", border: "1px dashed rgba(255,255,255,.18)", color: "rgba(255,255,255,.6)", fontSize: 11.5, fontWeight: 600, cursor: "pointer" }}>
              <ArrowLeft style={{ width: 12, height: 12 }} />
              {lang === "es" ? "¿Email incorrecto? Volver al formulario" : "Wrong email? Back to form"}
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ minHeight: "100vh", background: "linear-gradient(135deg,var(--deep),var(--ink))", display: "flex", alignItems: "center", justifyContent: "center", padding: 20, paddingTop: 100, paddingBottom: 40 }}>
      <div style={{ maxWidth: 480, width: "100%", background: "rgba(255,255,255,.04)", border: "1px solid rgba(255,255,255,.08)", borderRadius: 24, padding: "36px 32px", position: "relative", overflow: "hidden" }}>
        <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 4, background: "linear-gradient(90deg,var(--gold),var(--orange),var(--green),var(--sky))" }} />
        <div style={{ textAlign: "center", marginBottom: 24 }}>
          <div style={{ width: 64, height: 64, borderRadius: 18, background: "linear-gradient(135deg,var(--gold),var(--orange))", margin: "0 auto 16px", display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 12px 32px rgba(239,108,43,.3)" }}>
            <User style={{ width: 28, height: 28, color: "#fff" }} />
          </div>
          <h1 style={{ fontFamily: "Bebas Neue", fontSize: 30, letterSpacing: ".04em", marginBottom: 6 }}>{t("registerTitle")}</h1>
          <p style={{ fontSize: 13, color: "rgba(255,255,255,.6)" }}>{t("registerSub")}</p>
        </div>

        {/* "Quick Sign Up / One-Click" removido: el flujo Google/Apple/Facebook
            no está implementado y mostraba un modal "Coming soon" engañoso.
            Si se habilita OAuth en el futuro, se restaura desde git history. */}

        {/* Form */}
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 12 }}>
          <div>
            <label className="f-lab">{lang==="es"?"Nombre":"First Name"}</label>
            <input className="f-in" placeholder={lang==="es"?"Juana":"Jane"} value={form.firstName} onChange={(e) => setForm(f => ({ ...f, firstName: e.target.value }))} />
          </div>
          <div>
            <label className="f-lab">{lang==="es"?"Apellido":"Last Name"}</label>
            <input className="f-in" placeholder={lang==="es"?"Pérez":"Doe"} value={form.lastName} onChange={(e) => setForm(f => ({ ...f, lastName: e.target.value }))} />
          </div>
        </div>

        <div className="f-grp">
          <label className="f-lab">{lang==="es"?"Correo":"Email"}</label>
          <div style={{ position: "relative" }}>
            <input type="email" className="f-in" placeholder="you@email.com" value={form.email}
              onChange={(e) => setForm(f => ({ ...f, email: e.target.value }))}
              style={{ paddingRight: form.email ? 38 : 16, borderColor: !emailValid ? "rgba(239,108,43,.5)" : undefined }} />
            {form.email && (
              <div style={{ position: "absolute", right: 12, top: "50%", transform: "translateY(-50%)" }}>
                {emailValid ? <Check style={{ width: 16, height: 16, color: "#8DC63F" }} /> : <X style={{ width: 16, height: 16, color: "#EF6C2B" }} />}
              </div>
            )}
          </div>
          {form.email && !emailValid && <p style={{ fontSize: 11, color: "#EF6C2B", marginTop: 4 }}>{lang==="es"?"Ingresá un correo válido":"Enter a valid email address"}</p>}
        </div>

        <div className="f-grp">
          <label className="f-lab">
            {lang === "es" ? "WhatsApp" : "WhatsApp"} *
            <span style={{ color: "rgba(255,255,255,.45)", fontWeight: 400, textTransform: "none", letterSpacing: 0, marginLeft: 6 }}>
              {lang === "es" ? "(con código de país)" : "(with country code)"}
            </span>
          </label>
          <input
            type="tel"
            className="f-in"
            placeholder="+1 787 555 1234"
            value={form.phone}
            onChange={(e) => setForm(f => ({ ...f, phone: e.target.value }))}
            autoComplete="tel"
          />
          <p style={{ fontSize: 11, color: "rgba(255,255,255,.5)", marginTop: 4, lineHeight: 1.45 }}>
            {lang === "es"
              ? "Te contactaremos por WhatsApp para coordinar reservas y enviarte la factura/recibos."
              : "We'll reach out via WhatsApp to coordinate bookings and send invoices/receipts."}
          </p>
        </div>

        <div className="f-grp">
          <label className="f-lab">
            {lang === "es" ? "Fecha de nacimiento" : "Date of birth"} *
          </label>
          <input
            type="date"
            className="f-in"
            value={form.birthDate}
            max={new Date().toISOString().slice(0, 10)}
            onChange={(e) => setForm(f => ({ ...f, birthDate: e.target.value }))}
          />
          <p style={{ fontSize: 11, color: "rgba(255,255,255,.5)", marginTop: 4, lineHeight: 1.45 }}>
            {lang === "es"
              ? "La usamos para campañas de cumpleaños y ofertas personalizadas. Mínimo 13 años."
              : "Used for birthday campaigns and personalized offers. Minimum age 13."}
          </p>
        </div>

        <div className="f-grp">
          <label className="f-lab">{lang==="es"?"Contraseña":"Password"}</label>
          <div style={{ position: "relative" }}>
            <input type={showPwd ? "text" : "password"} className="f-in" placeholder={lang==="es"?"Al menos 8 caracteres":"At least 8 characters"} value={form.password}
              onChange={(e) => setForm(f => ({ ...f, password: e.target.value }))}
              style={{ paddingRight: 42 }} />
            <button type="button" onClick={() => setShowPwd(!showPwd)} style={{ position: "absolute", right: 8, top: "50%", transform: "translateY(-50%)", background: "transparent", border: "none", color: "rgba(255,255,255,.5)", cursor: "pointer", padding: 6 }}>
              {showPwd ? <EyeOff style={{ width: 15, height: 15 }} /> : <Eye style={{ width: 15, height: 15 }} />}
            </button>
          </div>
          {form.password && (
            <div style={{ marginTop: 8 }}>
              <div style={{ display: "flex", gap: 3, marginBottom: 4 }}>
                {[1,2,3,4,5].map(i => (
                  <div key={i} style={{ flex: 1, height: 3, borderRadius: 2, background: i <= pwdStrength.score ? pwdStrength.color : "rgba(255,255,255,.08)", transition: "background .2s" }} />
                ))}
              </div>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 10.5 }}>
                <span style={{ color: "rgba(255,255,255,.4)" }}>{lang==="es"?"Fortaleza de contraseña:":"Password strength:"}</span>
                <span style={{ color: pwdStrength.color, fontWeight: 700 }}>{pwdStrength.label}</span>
              </div>
            </div>
          )}
        </div>

        <div className="f-grp">
          <label className="f-lab">{lang==="es"?"Confirmar contraseña":"Confirm Password"}</label>
          <div style={{ position: "relative" }}>
            <input type={showPwdConfirm ? "text" : "password"} className="f-in" placeholder={lang==="es"?"Reingresá la contraseña":"Re-enter password"} value={form.confirmPassword}
              onChange={(e) => setForm(f => ({ ...f, confirmPassword: e.target.value }))}
              style={{ paddingRight: 70, borderColor: form.confirmPassword && !passwordsMatch ? "rgba(239,108,43,.5)" : undefined }} />
            <div style={{ position: "absolute", right: 8, top: "50%", transform: "translateY(-50%)", display: "flex", alignItems: "center", gap: 4 }}>
              {form.confirmPassword && (passwordsMatch ? <Check style={{ width: 15, height: 15, color: "#8DC63F" }} /> : <X style={{ width: 15, height: 15, color: "#EF6C2B" }} />)}
              <button type="button" onClick={() => setShowPwdConfirm(!showPwdConfirm)} style={{ background: "transparent", border: "none", color: "rgba(255,255,255,.5)", cursor: "pointer", padding: 6 }}>
                {showPwdConfirm ? <EyeOff style={{ width: 15, height: 15 }} /> : <Eye style={{ width: 15, height: 15 }} />}
              </button>
            </div>
          </div>
          {form.confirmPassword && !passwordsMatch && <p style={{ fontSize: 11, color: "#EF6C2B", marginTop: 4 }}>{lang==="es"?"Las contraseñas no coinciden":"Passwords do not match"}</p>}
        </div>

        <div className="f-grp">
          <label className="f-lab">{lang === "es" ? "País" : "Country"} <span style={{ color: "rgba(255,255,255,.35)", fontWeight: 400, textTransform: "none", letterSpacing: 0 }}>({lang === "es" ? "opcional" : "optional"})</span></label>
          <select className="f-in" value={form.country} onChange={(e) => setForm(f => ({ ...f, country: e.target.value }))}>
            <option value="">{lang === "es" ? "Selecciona tu país…" : "Select your country…"}</option>
            {COUNTRIES.map((c) => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>

        {/* Checkboxes */}
        <div style={{ display: "flex", flexDirection: "column", gap: 10, margin: "16px 0" }}>
          <label style={{ display: "flex", alignItems: "flex-start", gap: 9, cursor: "pointer", fontSize: 12.5, color: "rgba(255,255,255,.7)", lineHeight: 1.5 }}>
            <input type="checkbox" checked={form.acceptTerms} onChange={(e) => setForm(f => ({ ...f, acceptTerms: e.target.checked }))}
              style={{ accentColor: "#F5A623", width: 16, height: 16, marginTop: 1, flexShrink: 0 }} />
            <span>{lang === "es" ? "Acepto los " : "I accept the "}<a href="#/terms" target="_blank" rel="noopener noreferrer" style={{ color: "var(--gold)", textDecoration: "underline" }}>{lang === "es" ? "Términos y Condiciones" : "Terms & Conditions"}</a></span>
          </label>
          <label style={{ display: "flex", alignItems: "flex-start", gap: 9, cursor: "pointer", fontSize: 12.5, color: "rgba(255,255,255,.7)", lineHeight: 1.5 }}>
            <input type="checkbox" checked={form.acceptPrivacy} onChange={(e) => setForm(f => ({ ...f, acceptPrivacy: e.target.checked }))}
              style={{ accentColor: "#F5A623", width: 16, height: 16, marginTop: 1, flexShrink: 0 }} />
            <span>{lang === "es" ? "Acepto la " : "I accept the "}<a href="#/privacy" target="_blank" rel="noopener noreferrer" style={{ color: "var(--gold)", textDecoration: "underline" }}>{lang === "es" ? "Política de Privacidad" : "Privacy Policy"}</a></span>
          </label>
        </div>

        {error && (
          <div style={{ padding: 12, borderRadius: 10, background: "rgba(248,113,113,.1)", border: "1px solid rgba(248,113,113,.3)", color: "#f87171", fontSize: 12.5, marginBottom: 14, display: "flex", alignItems: "center", gap: 8 }}>
            <AlertTriangle style={{ width: 14, height: 14, flexShrink: 0 }} />
            <span>{error}</span>
          </div>
        )}

        <button type="button" onClick={handleRegister} disabled={loading} className="f-submit">
          {loading ? "..." : <><CheckCircle style={{ width: 14, height: 14 }} />{t("createAccount")}</>}
        </button>

        <div style={{ textAlign: "center", marginTop: 18, fontSize: 13, color: "rgba(255,255,255,.5)" }}>
          {t("alreadyHave")} <NavLink to="/login" style={{ color: "var(--gold)", fontWeight: 700, textDecoration: "none" }}>{t("signIn")}</NavLink>
        </div>
        <div style={{ textAlign: "center", marginTop: 10 }}>
          <NavLink to="/" style={{ fontSize: 12, color: "rgba(255,255,255,.4)" }}>{t("backToSite")}</NavLink>
        </div>
      </div>
    </div>
  );
}

/* ═══════════════ FORGOT PASSWORD ═══════════════ */
function ForgotPasswordPage() {
  const { t } = useLang();
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [sent, setSent] = useState(false);

  useEffect(() => {
    document.title = "Reset Password — Living in PRDISE";
  }, []);

  const handleSend = async () => {
    setError("");
    if (!email.trim()) { setError("Please enter your email"); return; }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { setError("Please enter a valid email address"); return; }
    setLoading(true);
    try {
      const fd = new FormData();
      fd.append("email", email.trim().toLowerCase());
      await sbRequestPasswordReset(fd);
      // Siempre marcamos como enviado, sin revelar si el email existe (anti-enumeration).
      setSent(true);
    } catch (e) {
      setError("Error de red. Intenta de nuevo en unos segundos.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ minHeight: "100vh", background: "linear-gradient(135deg,var(--deep),var(--ink))", display: "flex", alignItems: "center", justifyContent: "center", padding: 20, paddingTop: 100 }}>
      <div style={{ maxWidth: 420, width: "100%", background: "rgba(255,255,255,.04)", border: "1px solid rgba(255,255,255,.08)", borderRadius: 24, padding: "40px 32px", position: "relative", overflow: "hidden" }}>
        <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 4, background: "linear-gradient(90deg,var(--gold),var(--orange),var(--green),var(--sky))" }} />
        {sent ? (
          <>
            <div style={{ textAlign: "center", marginBottom: 20 }}>
              <div style={{ width: 64, height: 64, borderRadius: 18, background: "linear-gradient(135deg,#8DC63F,#22C55E)", margin: "0 auto 16px", display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 12px 32px rgba(141,198,63,.3)" }}>
                <Send style={{ width: 26, height: 26, color: "#fff" }} />
              </div>
              <h1 style={{ fontFamily: "Bebas Neue", fontSize: 28, letterSpacing: ".04em", marginBottom: 8 }}>{t("checkInbox")}</h1>
              <p style={{ fontSize: 13, color: "rgba(255,255,255,.6)", lineHeight: 1.6 }}>
                We've sent a password reset link to<br/>
                <strong style={{ color: "#fff" }}>{email}</strong>
              </p>
              <p style={{ fontSize: 11, color: "rgba(255,255,255,.4)", marginTop: 12, lineHeight: 1.6 }}>
                Didn't receive it? Check your spam folder or <button onClick={() => setSent(false)} style={{ background: "none", border: "none", color: "var(--gold)", textDecoration: "underline", cursor: "pointer", padding: 0, fontSize: "inherit" }}>try another email</button>.
              </p>
            </div>
            <div style={{ textAlign: "center", marginTop: 24, paddingTop: 20, borderTop: "1px solid rgba(255,255,255,.06)" }}>
              <NavLink to="/login" style={{ fontFamily: "Dancing Script, cursive", fontSize: 16, color: "var(--gold)", textDecoration: "underline", textUnderlineOffset: 3 }}>
                Back to sign in
              </NavLink>
            </div>
          </>
        ) : (
          <>
            <div style={{ textAlign: "center", marginBottom: 24 }}>
              <div style={{ width: 64, height: 64, borderRadius: 18, background: "linear-gradient(135deg,var(--gold),var(--orange))", margin: "0 auto 16px", display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 12px 32px rgba(239,108,43,.3)" }}>
                <Key style={{ width: 26, height: 26, color: "#fff" }} />
              </div>
              <h1 style={{ fontFamily: "Bebas Neue", fontSize: 28, letterSpacing: ".04em", marginBottom: 8 }}>{t("resetTitle")}</h1>
              <p style={{ fontSize: 13, color: "rgba(255,255,255,.6)", lineHeight: 1.6 }}>{t("resetSub")}</p>
            </div>

            <div className="f-grp">
              <label className="f-lab">Email</label>
              <input type="email" className="f-in" placeholder="you@email.com" value={email}
                onChange={(e) => setEmail(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && handleSend()} />
            </div>

            {error && (
              <div style={{ padding: 12, borderRadius: 10, background: "rgba(248,113,113,.1)", border: "1px solid rgba(248,113,113,.3)", color: "#f87171", fontSize: 12.5, marginBottom: 14, display: "flex", alignItems: "center", gap: 8 }}>
                <AlertTriangle style={{ width: 14, height: 14, flexShrink: 0 }} />
                <span>{error}</span>
              </div>
            )}

            <button type="button" onClick={handleSend} disabled={loading} className="f-submit">
              {loading ? "..." : <><Send style={{ width: 14, height: 14 }} />{t("sendLink")}</>}
            </button>

            <div style={{ textAlign: "center", marginTop: 20 }}>
              <NavLink to="/login" style={{ fontFamily: "Dancing Script, cursive", fontSize: 16, color: "rgba(255,255,255,.55)", textDecoration: "underline", textUnderlineOffset: 3 }}>
                Back to sign in
              </NavLink>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

