              <button className={`adm-fchip ${hotelsFilter === "draft" ? "active" : ""}`} onClick={() => setHotelsFilter("draft")}>{lang==="es"?"Borradores":"Drafts"} <span className="adm-fchip-num">{hotels.filter(h => h.status === "draft").length}</span></button>
