function IntegrationsPanel() {
  const { lang } = useLang();
  // PM 2026-06-11: ahora sí se puede conectar Stripe y PayPal desde el panel.
  // El estado viene de payment_provider_configs (RLS admin-only). Las keys
  // se guardan server-side y nunca se exponen al cliente más allá del modal
  // de configuración del admin que las introdujo.
  const [configs, setConfigs] = useState({});
  const [openModal, setOpenModal] = useState(null);
  const reload = async () => {
    try {
      const rows = await sbListPaymentConfigs();
      const map = {};
      (rows || []).forEach((r) => { map[r.provider] = r; });
      setConfigs(map);
    } catch (e) { console.warn("[admin] payment configs:", e); }
  };
  useEffect(() => { reload(); }, []);

  return (
    <>
      <div className="adm-card">
        <div className="adm-card-head"><div className="adm-card-title">{lang==="es"?"Servicios Conectados":"Connected Services"}</div></div>
        {Object.entries(INTEGRATIONS_CONFIG).map(([id, cfg]) => {
          const row = configs[id];
          const isConnected = !!row?.enabled;
          return (
            <div key={id} className="adm-srow">
              <div className="adm-srow-info" style={{ display: "flex", alignItems: "center", gap: 12 }}>
                <div style={{ width: 36, height: 36, borderRadius: 9, background: cfg.color + "22", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                  <div style={{ width: 14, height: 14, borderRadius: 3, background: cfg.color }} />
                </div>
                <div>
                  <h5>
                    {cfg.name}
                    {isConnected && (
                      <span style={{ marginLeft: 8, fontSize: 10, color: "#8DC63F", fontWeight: 800 }}>
                        ● {lang==="es"?"CONECTADO":"CONNECTED"}
                        {row?.mode && <span style={{ marginLeft: 6, color: "rgba(255,255,255,.4)", fontWeight: 700 }}>({row.mode === "live" ? "LIVE" : "TEST"})</span>}
                      </span>
                    )}
                  </h5>
                  <p>{lang==="es"?cfg.descES:cfg.descEN}</p>
                </div>
              </div>
              <div style={{ display: "flex", gap: 8 }}>
                <button className="adm-btn adm-btn-ghost" onClick={() => setOpenModal(id)}>
                  <Settings />{isConnected ? (lang === "es" ? "Configurar" : "Configure") : (lang === "es" ? "Conectar" : "Connect")}
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {openModal && (
        <IntegrationModal
          integrationId={openModal}
          config={INTEGRATIONS_CONFIG[openModal]}
          initialData={configs[openModal] || {}}
          isConnected={!!configs[openModal]?.enabled}
          onClose={() => setOpenModal(null)}
          onSave={async (data) => {
            const fd = new FormData();
            fd.append("provider", openModal);
            fd.append("enabled", data.enabled ? "true" : "false");
            fd.append("mode", data.mode || "test");
            if (openModal === "stripe") {
              fd.append("publishable_key", data.publishable_key || "");
              fd.append("secret_key", data.secret_key || "");
              fd.append("webhook_secret", data.webhook_secret || "");
              fd.append("connected_account_id", data.connected_account_id || "");
            } else {
              fd.append("client_id", data.client_id || "");
              fd.append("client_secret", data.client_secret || "");
              fd.append("account_email", data.account_email || "");
            }
            fd.append("default_currency", data.default_currency || "USD");
            const res = await sbSavePaymentConfig(fd);
            if (!res?.ok) { alert(res?.error || "Error"); return; }
            setOpenModal(null);
            reload();
          }}
        />
      )}
    </>
  );
}

function IntegrationModal({ integrationId, config, initialData, isConnected, onClose, onSave }) {
  const { lang } = useLang();
  const [data, setData] = useState(initialData);
  const [showSecret, setShowSecret] = useState({});
  const [error, setError] = useState("");
  const [saved, setSaved] = useState(false);

  const labelOf = (f) => lang === "es" ? (f.labelES || f.label || f.labelEN) : (f.labelEN || f.label || f.labelES);

  const handleSave = () => {
    setError("");
    // Si la integración va a quedar activa, validar campos required. Si
    // queda inactiva, el admin puede guardar config parcial para volver
    // después sin perder lo tipeado.
    if (data.enabled) {
      for (const f of config.fields) {
        if (f.required && !String(data[f.key] || "").trim()) {
          setError(lang==="es" ? `"${labelOf(f)}" es requerido para activar la integración.` : `"${labelOf(f)}" is required to enable this integration.`);
          return;
        }
      }
    }
    setSaved(true);
    setTimeout(() => onSave(data), 600);
  };

  return (
    <div className="adm-modal-bg" onClick={onClose}>
      <div className="adm-modal" onClick={(e) => e.stopPropagation()} style={{ maxWidth: 540 }}>
        <button className="adm-modal-close" onClick={onClose}><X /></button>
        <div style={{ display: "flex", alignItems: "center", gap: 14, marginBottom: 8 }}>
          <div style={{ width: 46, height: 46, borderRadius: 11, background: config.color + "22", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
            <div style={{ width: 18, height: 18, borderRadius: 4, background: config.color }} />
          </div>
          <div>
            <h3 style={{ marginBottom: 2 }}>{isConnected ? (lang==="es"?"CONFIGURAR":"CONFIGURE") : (lang==="es"?"CONECTAR":"CONNECT")} {config.name.toUpperCase()}</h3>
            <p className="adm-modal-sub" style={{ marginBottom: 0 }}>{lang==="es"?config.descES:config.descEN}</p>
          </div>
        </div>
        <div style={{ borderTop: "1px solid rgba(255,255,255,.06)", paddingTop: 18, marginTop: 18 }}>
          {/* Habilitar/deshabilitar la integración. Si guardás con
              enabled=true sin llenar las keys requeridas, el server rechaza. */}
          <label style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 14px", borderRadius: 10, background: data.enabled ? "rgba(141,198,63,.1)" : "rgba(255,255,255,.04)", border: data.enabled ? "1px solid rgba(141,198,63,.3)" : "1px solid rgba(255,255,255,.08)", cursor: "pointer", marginBottom: 14 }}>
            <input type="checkbox" checked={!!data.enabled} onChange={(e) => setData({ ...data, enabled: e.target.checked })} />
            <div>
              <div style={{ fontSize: 12.5, fontWeight: 700, color: "#fff" }}>
                {lang === "es" ? "Activar esta integración" : "Enable this integration"}
              </div>
              <div style={{ fontSize: 11, color: "rgba(255,255,255,.55)", marginTop: 2 }}>
                {lang === "es"
                  ? "Cuando esté activada, esta integración se usará al generar links de pago en facturas."
                  : "When enabled, this integration is used when generating payment links on invoices."}
              </div>
            </div>
          </label>
          {config.fields.map((f) => (
            <div key={f.key} className="adm-fg">
              <label className="adm-fl">
                {labelOf(f)} {f.required && <span style={{ color: "#EF6C2B" }}>*</span>}
              </label>
              {f.type === "select" ? (
                <select className="adm-fi" value={data[f.key] || ""} onChange={(e) => setData({ ...data, [f.key]: e.target.value })}>
                  <option value="">{lang==="es"?"Seleccionar...":"Select..."}</option>
                  {f.options.map((o) => <option key={o} value={o}>{o}</option>)}
                </select>
              ) : (
                <div style={{ position: "relative" }}>
                  <input
                    type={f.secret && !showSecret[f.key] ? "password" : "text"}
                    className="adm-fi"
                    placeholder={f.placeholder}
                    value={data[f.key] || ""}
                    onChange={(e) => setData({ ...data, [f.key]: e.target.value })}
                    style={f.secret ? { paddingRight: 38 } : {}}
                  />
                  {f.secret && (
                    <button type="button" onClick={() => setShowSecret({ ...showSecret, [f.key]: !showSecret[f.key] })}
                      style={{ position: "absolute", right: 8, top: "50%", transform: "translateY(-50%)", background: "transparent", border: "none", color: "rgba(255,255,255,.5)", cursor: "pointer", padding: 6 }}>
                      {showSecret[f.key] ? <EyeOff style={{ width: 14, height: 14 }} /> : <Eye style={{ width: 14, height: 14 }} />}
                    </button>
                  )}
                </div>
              )}
            </div>
          ))}
        </div>

        {error && (
          <div style={{ padding: 11, borderRadius: 9, background: "rgba(248,113,113,.1)", border: "1px solid rgba(248,113,113,.3)", color: "#f87171", fontSize: 12.5, marginTop: 14, display: "flex", alignItems: "center", gap: 8 }}>
            <AlertTriangle style={{ width: 14, height: 14, flexShrink: 0 }} />
            <span>{error}</span>
          </div>
        )}

        <div style={{ padding: 12, borderRadius: 10, background: "rgba(41,171,226,.08)", border: "1px solid rgba(41,171,226,.2)", marginTop: 14, display: "flex", gap: 10, alignItems: "flex-start" }}>
          <Info style={{ width: 14, height: 14, color: "#29ABE2", flexShrink: 0, marginTop: 2 }} />
          <p style={{ fontSize: 12, color: "rgba(255,255,255,.65)", margin: 0, lineHeight: 1.55 }}>
            {lang==="es"?"Tus credenciales están encriptadas y almacenadas de forma segura. Nunca compartas tus claves secretas públicamente.":"Your credentials are encrypted and stored securely. Never share your secret keys publicly."}
          </p>
        </div>

        <div className="adm-modal-actions">
          <button className="adm-btn adm-btn-ghost" onClick={onClose}>{lang==="es"?"Cancelar":"Cancel"}</button>
          <button className="adm-btn adm-btn-primary" onClick={handleSave}>
            <Check />{saved ? (lang==="es"?"Guardado ✓":"Saved ✓") : isConnected ? (lang==="es"?"Guardar cambios":"Save Changes") : (lang==="es"?"Conectar":"Connect")}
          </button>
        </div>
      </div>
    </div>
  );
}

function IntegRow({ name, desc, connected }) {
  const [c, setC] = useState(connected || false);
  return (
    <div className="adm-srow">
      <div className="adm-srow-info">
        <h5>{name} {c && <span style={{ marginLeft: 8, fontSize: 10, color: "#8DC63F", fontWeight: 800 }}>● CONNECTED</span>}</h5>
        <p>{desc}</p>
      </div>
      <button className={`adm-btn ${c ? "adm-btn-ghost" : "adm-btn-primary"}`} onClick={() => setC(!c)}>
        {c ? "Disconnect" : "Connect"}
      </button>
    </div>
  );
}

/* ═══════════════ CUSTOM ROLE EDIT MODAL ═══════════════ */
// Crea o edita un rol custom: name (kebab), labels ES/EN, descripción y
// matriz de permisos agrupada por área. Submit usa createCustomRole o
// updateCustomRole según role.id === "new".
/* ═══════════════ AUTH TOOLS PANEL ═══════════════ */
// Workarounds para SMTP roto: genera links de confirmación/recovery sin
// enviar email (admin copia y manda al cliente por WhatsApp/etc), o fuerza
// la confirmación de un email cuando el cliente es de confianza. Todo es
// admin-only (RLS en lib/admin/auth_tools.ts via getAdminOrError).
function AuthToolsPanel({ lang }) {
  const [email, setEmail] = useState("");
  const [busy, setBusy] = useState(null); // 'link' | 'force' | 'recovery' | null
  const [result, setResult] = useState(null); // { kind, url?, msg? }
  const [error, setError] = useState("");
  // PM 2026-06-12: autocomplete no-exclusivo. El admin puede tipear cualquier
  // correo (no se restringe a resultados) pero si tipea 2+ caracteres,
  // mostramos sugerencias de usuarios existentes para facilitar la búsqueda.
  const [suggestions, setSuggestions] = useState([]);
  const [suggOpen, setSuggOpen] = useState(false);
  useEffect(() => {
    if (!email || email.trim().length < 2) { setSuggestions([]); return; }
    const id = setTimeout(async () => {
      try {
        const fd = new FormData();
        fd.append("q", email.trim());
        const res = await sbSearchProfiles(fd);
        setSuggestions(res?.ok ? (res.data?.results ?? []) : []);
      } catch { setSuggestions([]); }
    }, 250);
    return () => clearTimeout(id);
  }, [email]);

  const run = async (kind, fn) => {
    setBusy(kind);
    setError("");
    setResult(null);
    try {
      const fd = new FormData();
      fd.append("email", email);
      const res = await fn(fd);
      if (!res?.ok) {
        setError(res?.error || (lang === "es" ? "Error desconocido" : "Unknown error"));
        return;
      }
      setResult({ kind, ...(res.data || {}) });
    } catch (e) {
      setError(e?.message || String(e));
    } finally {
      setBusy(null);
    }
  };

  const copy = (txt) => {
    try {
      navigator.clipboard.writeText(txt);
      alert(lang === "es" ? "Copiado al portapapeles." : "Copied to clipboard.");
    } catch {}
  };

  return (
    <div className="adm-card">
      <div className="adm-card-head">
        <div className="adm-card-title"><Lock />{lang === "es" ? "Herramientas de Autenticación" : "Auth Tools"}</div>
      </div>
      <p style={{ fontSize: 12.5, color: "rgba(255,255,255,.55)", marginTop: -4, marginBottom: 14, lineHeight: 1.6 }}>
        {lang === "es"
          ? "Si el correo automático no le llegó al cliente (por estar en spam, por bloqueo del proveedor o cualquier otro motivo), generá acá el link de confirmación o de cambio de contraseña y enviáselo manualmente por WhatsApp. También podés confirmar la cuenta directamente si ya verificaste la identidad del cliente."
          : "If the automated email did not reach the customer (spam, provider block, or any other reason), generate the confirmation or password-reset link here and send it manually via WhatsApp. You can also confirm the account directly if you have already verified the customer's identity."}
      </p>

      <div className="adm-fg" style={{ position: "relative" }}>
        <label className="adm-fl">{lang === "es" ? "Email del usuario" : "User email"}</label>
        <input
          className="adm-fi"
          type="email"
          value={email}
          onChange={(e) => { setEmail(e.target.value); setSuggOpen(true); }}
          onFocus={() => setSuggOpen(true)}
          onBlur={() => setTimeout(() => setSuggOpen(false), 150)}
          placeholder="cliente@ejemplo.com"
          autoComplete="off"
        />
        {suggOpen && suggestions.length > 0 && (
          <div style={{ position: "absolute", top: "100%", left: 0, right: 0, marginTop: 4, maxHeight: 220, overflowY: "auto", background: "#1A2634", border: "1px solid rgba(255,255,255,.1)", borderRadius: 10, boxShadow: "0 10px 32px rgba(0,0,0,.5)", zIndex: 50 }}>
            {suggestions.map((s) => {
              const display = [s.first_name, s.last_name].filter(Boolean).join(" ") || s.email || (lang === "es" ? "(sin nombre)" : "(no name)");
              return (
                <button
                  key={s.id}
                  type="button"
                  onMouseDown={(e) => { e.preventDefault(); setEmail(s.email || ""); setSuggOpen(false); }}
                  style={{ display: "block", width: "100%", textAlign: "left", padding: "9px 12px", background: "transparent", border: "none", borderBottom: "1px solid rgba(255,255,255,.05)", color: "#fff", cursor: "pointer", fontSize: 12.5 }}
                  onMouseEnter={(e) => e.currentTarget.style.background = "rgba(245,166,35,.08)"}
                  onMouseLeave={(e) => e.currentTarget.style.background = "transparent"}
                >
                  <div style={{ fontWeight: 600 }}>{display}</div>
                  <div style={{ fontSize: 11, color: "rgba(255,255,255,.5)" }}>
                    {s.email || "—"}{s.phone ? ` · ${s.phone}` : ""}
                    {(s.id || "").startsWith("ghost-") && <span style={{ marginLeft: 6, fontSize: 9, padding: "1px 6px", borderRadius: 3, background: "rgba(245,166,35,.18)", color: "#F5A623", fontWeight: 800, letterSpacing: ".05em" }}>{lang === "es" ? "SIN PERFIL" : "NO PROFILE"}</span>}
                  </div>
                </button>
              );
            })}
          </div>
        )}
        <p style={{ fontSize: 10.5, color: "rgba(255,255,255,.4)", marginTop: 4, lineHeight: 1.5 }}>
          {lang === "es"
            ? "Las sugerencias son solo una ayuda — podés tipear cualquier correo aunque no esté en la lista."
            : "Suggestions are a helper only — you can type any email even if not in the list."}
        </p>
      </div>

      <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginTop: 8 }}>
        <button
          className="adm-btn adm-btn-primary"
          onClick={() => run("link", sbGenerateSignupConfirmLink)}
          disabled={!email || busy !== null}
        >
          {busy === "link" ? <Loader2 style={{ width: 13, height: 13, animation: "spin 1s linear infinite" }} /> : <Mail />}
          {lang === "es" ? "Generar link de confirmación" : "Generate signup link"}
        </button>
        <button
          className="adm-btn adm-btn-ghost"
          onClick={() => run("recovery", sbGenerateRecoveryLink)}
          disabled={!email || busy !== null}
        >
          {busy === "recovery" ? <Loader2 style={{ width: 13, height: 13, animation: "spin 1s linear infinite" }} /> : <Key />}
          {lang === "es" ? "Link de reset password" : "Password reset link"}
        </button>
        <button
          className="adm-btn adm-btn-ghost"
          onClick={() => {
            if (!confirm(lang === "es"
              ? `¿Confirmar manualmente el email "${email}" sin verificar? Solo úsalo con usuarios de confianza.`
              : `Manually confirm "${email}" without verification? Only use for trusted users.`)) return;
            run("force", sbForceConfirmEmail);
          }}
          disabled={!email || busy !== null}
        >
          {busy === "force" ? <Loader2 style={{ width: 13, height: 13, animation: "spin 1s linear infinite" }} /> : <CheckCircle />}
          {lang === "es" ? "Forzar confirmación" : "Force confirm"}
        </button>
      </div>

      {error && (
        <div style={{ marginTop: 14, padding: "10px 12px", borderRadius: 9, background: "rgba(239,68,68,.1)", border: "1px solid rgba(239,68,68,.3)", color: "#f87171", fontSize: 12.5, display: "flex", alignItems: "center", gap: 8 }}>
          <AlertTriangle style={{ width: 13, height: 13 }} /> {error}
        </div>
      )}

      {result && result.kind === "force" && (
        <div style={{ marginTop: 14, padding: "12px 14px", borderRadius: 10, background: "rgba(141,198,63,.1)", border: "1px solid rgba(141,198,63,.3)", color: "#8DC63F", fontSize: 13 }}>
          <CheckCircle style={{ width: 14, height: 14, display: "inline", marginRight: 6 }} />
          {lang === "es" ? "Email confirmado. El usuario ya puede iniciar sesión." : "Email confirmed. The user can sign in now."}
        </div>
      )}

      {result && result.url && (() => {
        // Pre-fill destinatario WhatsApp con el phone del cliente (registro)
        // si lo hay. Admin puede override con manualPhone state. Si no hay
        // phone, wa.me/?text=... abre WhatsApp sin destinatario y el admin
        // pega el contacto manualmente.
        const greeting = result.name ? (lang === "es" ? `Hola ${result.name},` : `Hi ${result.name},`) : (lang === "es" ? "Hola," : "Hi,");
        const linkMsg = result.kind === "link"
          ? (lang === "es" ? "este es tu link para confirmar tu cuenta en PRDISE. Ábrelo desde el mismo navegador donde vas a iniciar sesión:" : "here's your PRDISE account confirmation link. Open it in the same browser you'll sign in from:")
          : (lang === "es" ? "este es tu link para restablecer tu contraseña en PRDISE (válido ~1h):" : "here's your PRDISE password reset link (~1h valid):");
        const fullText = `${greeting} ${linkMsg}\n${result.url}`;
        const phoneDigits = (result.phone || "").replace(/\D/g, "");
        const waHref = phoneDigits
          ? `https://wa.me/${phoneDigits}?text=${encodeURIComponent(fullText)}`
          : `https://wa.me/?text=${encodeURIComponent(fullText)}`;
        return (
        <div style={{ marginTop: 14, padding: "14px 16px", borderRadius: 12, background: "rgba(245,166,35,.08)", border: "1px solid rgba(245,166,35,.3)" }}>
          <div style={{ fontSize: 11, fontWeight: 800, letterSpacing: ".1em", textTransform: "uppercase", color: "var(--gold)", marginBottom: 8 }}>
            {result.kind === "link"
              ? (lang === "es" ? "Link de confirmación (válido ~24h)" : "Confirmation link (~24h valid)")
              : (lang === "es" ? "Link de reset password (válido ~1h)" : "Password reset link (~1h valid)")}
          </div>
          {(result.phone || result.name) && (
            <div style={{ fontSize: 11.5, color: "rgba(255,255,255,.7)", marginBottom: 8, padding: "6px 10px", borderRadius: 8, background: "rgba(141,198,63,.08)", border: "1px solid rgba(141,198,63,.2)" }}>
              {lang === "es" ? "Destinatario: " : "To: "}
              <strong style={{ color: "#fff" }}>{result.name || email}</strong>
              {result.phone && <> · <code style={{ fontFamily: "monospace", color: "#8DC63F" }}>{result.phone}</code></>}
              {!result.phone && (
                <span style={{ marginLeft: 6, color: "#F5A623" }}>
                  ({lang === "es" ? "sin WhatsApp registrado — abre WhatsApp Web y elegí destinatario" : "no WhatsApp on file — pick contact in WhatsApp Web"})
                </span>
              )}
            </div>
          )}
          <code style={{ display: "block", padding: "10px 12px", borderRadius: 8, background: "rgba(0,0,0,.3)", fontSize: 11, color: "#fff", wordBreak: "break-all", fontFamily: "monospace", lineHeight: 1.5 }}>
            {result.url}
          </code>
          <div style={{ display: "flex", gap: 8, marginTop: 10, flexWrap: "wrap" }}>
            <button className="adm-btn adm-btn-primary" onClick={() => copy(result.url)} style={{ padding: "8px 14px" }}>
              <Copy style={{ width: 12, height: 12 }} />{lang === "es" ? "Copiar link" : "Copy link"}
            </button>
            <a
              href={waHref}
              target="_blank"
              rel="noopener noreferrer"
              className="adm-btn adm-btn-ghost"
              style={{ padding: "8px 14px", textDecoration: "none" }}
            >
              <MessageCircle style={{ width: 12, height: 12 }} />
              {result.phone
                ? (lang === "es" ? `Enviar por WhatsApp a ${result.phone}` : `Send WhatsApp to ${result.phone}`)
                : (lang === "es" ? "Abrir WhatsApp" : "Open WhatsApp")}
            </a>
          </div>
          <p style={{ fontSize: 11, color: "rgba(255,255,255,.45)", marginTop: 10, lineHeight: 1.5 }}>
            {lang === "es"
              ? "El cliente debe abrir el link en el mismo navegador donde va a iniciar sesión. Si lo abre en otro dispositivo, igual se confirma su cuenta y puede loguear normal."
              : "The customer should open the link in the same browser they'll sign in from. If opened on another device, the account still confirms and they can sign in normally."}
          </p>
        </div>
        );
      })()}
    </div>
  );
}

function CustomRoleEditModal({ role, lang, onClose, onSaved }) {
  const isNew = role.id === "new";
  const [form, setForm] = useState(() => ({
    name: role.name || "",
    label_es: role.label_es || "",
    label_en: role.label_en || "",
    description: role.description || "",
    active: role.active !== false,
  }));
  const [perms, setPerms] = useState(() => new Set(role.permissions || []));
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  const togglePerm = (key) => {
    setPerms((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key); else next.add(key);
      return next;
    });
  };
  const toggleArea = (area) => {
    const keysInArea = ALL_PERMISSION_KEYS.filter((k) => k.startsWith(area + ":"));
    const allChecked = keysInArea.every((k) => perms.has(k));
    setPerms((prev) => {
      const next = new Set(prev);
      if (allChecked) keysInArea.forEach((k) => next.delete(k));
      else keysInArea.forEach((k) => next.add(k));
      return next;
    });
  };

  const save = async () => {
    setError("");
    if (!form.name.trim() || !form.label_es.trim() || !form.label_en.trim()) {
      setError(lang === "es" ? "Nombre y etiquetas ES/EN son requeridos." : "Name and ES/EN labels are required.");
      return;
    }
    setSaving(true);
    try {
      const fd = new FormData();
      fd.append("name", form.name);
      fd.append("label_es", form.label_es);
      fd.append("label_en", form.label_en);
      fd.append("description", form.description);
      fd.append("active", form.active ? "true" : "false");
      fd.append("permissions", JSON.stringify(Array.from(perms)));
      if (!isNew) fd.append("id", role.id);
      const action = isNew ? sbCreateCustomRole : sbUpdateCustomRole;
      const res = await action(fd);
      if (!res?.ok) {
        setError(res?.error || (lang === "es" ? "No se pudo guardar" : "Could not save"));
        return;
      }
      onSaved?.();
    } catch (e) {
      setError(e?.message || String(e));
    } finally {
      setSaving(false);
    }
  };

  // Agrupar keys por área para la matriz visual.
  const byArea = PERMISSION_AREAS.map((area) => ({
    area,
    keys: ALL_PERMISSION_KEYS.filter((k) => k.startsWith(area + ":")),
  })).filter((g) => g.keys.length > 0);

  return (
    <div className="adm-modal-bg" onClick={onClose}>
      <div className="adm-modal" style={{ maxWidth: 720 }} onClick={(e) => e.stopPropagation()}>
        <button className="adm-modal-close" onClick={onClose}><X /></button>
        <h3>{isNew ? (lang === "es" ? "NUEVO ROL" : "NEW ROLE") : (lang === "es" ? "EDITAR ROL" : "EDIT ROLE")}</h3>
        <p className="adm-modal-sub">
          {lang === "es"
            ? "Define un rol custom y los permisos que otorga. Asignable a cualquier cliente desde su edición."
            : "Define a custom role and the permissions it grants. Assignable to any customer from their edit panel."}
        </p>

        <div className="adm-fg">
          <label className="adm-fl">{lang === "es" ? "Nombre interno (slug)" : "Internal name (slug)"} *</label>
          <input className="adm-fi" value={form.name} onChange={(e) => setForm((f) => ({ ...f, name: e.target.value.toLowerCase().replace(/[^a-z0-9_-]/g, "") }))} placeholder="content_manager" />
          <p style={{ fontSize: 10.5, color: "rgba(255,255,255,.4)", marginTop: 4 }}>
            {lang === "es" ? "Solo minúsculas, números, _ y -. Empieza con letra. No se puede cambiar después." : "Lowercase, numbers, _ and - only. Starts with a letter. Cannot change after creation."}
          </p>
        </div>
        <div className="adm-fg-row">
          <div className="adm-fg"><label className="adm-fl">{lang === "es" ? "Etiqueta ES" : "Spanish label"} *</label><input className="adm-fi" value={form.label_es} onChange={(e) => setForm((f) => ({ ...f, label_es: e.target.value }))} placeholder={lang === "es" ? "Gestor de Contenido" : "Gestor de Contenido"} /></div>
          <div className="adm-fg"><label className="adm-fl">{lang === "es" ? "Etiqueta EN" : "English label"} *</label><input className="adm-fi" value={form.label_en} onChange={(e) => setForm((f) => ({ ...f, label_en: e.target.value }))} placeholder="Content Manager" /></div>
        </div>
        <div className="adm-fg">
          <label className="adm-fl">{lang === "es" ? "Descripción" : "Description"}</label>
          <textarea className="adm-fi" rows={2} value={form.description} onChange={(e) => setForm((f) => ({ ...f, description: e.target.value }))} placeholder={lang === "es" ? "Qué puede hacer este rol y cuándo asignarlo" : "What this role can do and when to assign it"} />
        </div>
        <label style={{ display: "flex", alignItems: "center", gap: 9, padding: "10px 12px", borderRadius: 10, background: "rgba(141,198,63,.08)", border: "1px solid rgba(141,198,63,.2)", cursor: "pointer", marginBottom: 16 }}>
          <input type="checkbox" checked={form.active} onChange={(e) => setForm((f) => ({ ...f, active: e.target.checked }))} style={{ accentColor: "#8DC63F", width: 15, height: 15 }} />
          <span style={{ fontSize: 12.5, color: "rgba(255,255,255,.8)" }}>
            {lang === "es" ? "Activo (los usuarios con este rol mantienen sus permisos)" : "Active (users with this role keep their permissions)"}
          </span>
        </label>

        <h4 style={{ fontFamily: "Bebas Neue", fontSize: 14, letterSpacing: ".1em", color: "var(--gold)", margin: "14px 0 8px" }}>
          {lang === "es" ? "PERMISOS" : "PERMISSIONS"} <span style={{ fontSize: 11, color: "rgba(255,255,255,.4)", marginLeft: 6 }}>({perms.size} {lang === "es" ? "seleccionados" : "selected"})</span>
        </h4>
        <div style={{ maxHeight: 320, overflowY: "auto", padding: 4, border: "1px solid rgba(255,255,255,.08)", borderRadius: 10 }}>
          {byArea.map((g) => {
            const allChecked = g.keys.every((k) => perms.has(k));
            const someChecked = !allChecked && g.keys.some((k) => perms.has(k));
            return (
              <div key={g.area} style={{ padding: "10px 12px", borderBottom: "1px solid rgba(255,255,255,.05)" }}>
                <label style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6, cursor: "pointer" }}>
                  <input type="checkbox" checked={allChecked} ref={(el) => { if (el) el.indeterminate = someChecked; }} onChange={() => toggleArea(g.area)} style={{ accentColor: "var(--gold)", width: 15, height: 15 }} />
                  <span style={{ fontFamily: "Bebas Neue", fontSize: 13, letterSpacing: ".1em", color: "#fff", textTransform: "uppercase" }}>{g.area}</span>
                </label>
                <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(180px,1fr))", gap: 6, paddingLeft: 22 }}>
                  {g.keys.map((k) => (
                    <label key={k} style={{ display: "flex", alignItems: "center", gap: 7, fontSize: 11.5, color: "rgba(255,255,255,.7)", cursor: "pointer" }}>
                      <input type="checkbox" checked={perms.has(k)} onChange={() => togglePerm(k)} style={{ accentColor: "var(--gold)", width: 13, height: 13 }} />
                      <code style={{ fontFamily: "monospace", fontSize: 11 }}>{k.split(":")[1]}</code>
                    </label>
                  ))}
                </div>
              </div>
            );
          })}
        </div>

        {error && (
          <div style={{ marginTop: 12, padding: "10px 12px", borderRadius: 9, background: "rgba(239,68,68,.1)", border: "1px solid rgba(239,68,68,.3)", color: "#f87171", fontSize: 12, display: "flex", alignItems: "center", gap: 8 }}>
            <AlertTriangle style={{ width: 13, height: 13 }} /> {error}
          </div>
        )}

        <div style={{ display: "flex", gap: 10, marginTop: 18, justifyContent: "flex-end" }}>
          <button className="adm-btn adm-btn-ghost" onClick={onClose} disabled={saving}>{lang === "es" ? "Cancelar" : "Cancel"}</button>
          <button className="adm-btn adm-btn-primary" onClick={save} disabled={saving}>
            {saving ? <Loader2 style={{ width: 14, height: 14, animation: "spin 1s linear infinite" }} /> : <Check />}
            {saving ? (lang === "es" ? "Guardando…" : "Saving…") : (isNew ? (lang === "es" ? "Crear rol" : "Create role") : (lang === "es" ? "Guardar cambios" : "Save changes"))}
          </button>
        </div>
      </div>
    </div>
  );
}

/* ═══════════════ INVOICE CREATE MODAL (Fase 2 pivote 2026-06-04) ═══════════════ */
function InvoiceCreateModal({ lang, onClose, onCreated }) {
  // ── Customer state ──────────────────────────────────────────────────────
  // Modo "buscar" arranca abierto. Al elegir un profile o crear uno nuevo,
  // los datos quedan locked y se muestra un summary editable.
  const [mode, setMode] = useState("search"); // "search" | "create" | "locked"
  const [search, setSearch] = useState("");
  const [searchResults, setSearchResults] = useState([]);
  const [searching, setSearching] = useState(false);
  const [selectedUserId, setSelectedUserId] = useState(null);
  const [customerName, setCustomerName] = useState("");
  const [customerEmail, setCustomerEmail] = useState("");
  const [customerPhone, setCustomerPhone] = useState("");
  const [customerWhatsapp, setCustomerWhatsapp] = useState("");
  // Nuevo cliente: si el admin crea uno desde acá, mostramos password 1 vez.
  const [newCustomerPwd, setNewCustomerPwd] = useState(null);

  // ── Invoice state ────────────────────────────────────────────────────────
  const [notes, setNotes] = useState("");
  const [dueAt, setDueAt] = useState("");
  // Método de pago (PM 2026-06-11): el admin elige cómo se cobrará. El link
  // de pago NO se genera automáticamente — se genera al hacer click desde la
  // lista de facturas cuando el admin esté listo.
  const [paymentMethod, setPaymentMethod] = useState("off_system");
  // Cada item: { description, quantity, unitPrice, tourId?, stayId?, transferRouteId? }
  const [items, setItems] = useState([{ description: "", quantity: 1, unitPrice: "" }]);
  const [error, setError] = useState("");
  const [submitting, setSubmitting] = useState(false);
  // PM 2026-06-24: vista previa antes de persistir. Nada se escribe en DB
  // ni se genera link de Stripe hasta que el admin confirma desde el preview.
  const [showPreview, setShowPreview] = useState(false);

  // ── Dedupe state ─────────────────────────────────────────────────────────
  const [duplicateMatches, setDuplicateMatches] = useState([]);
  const [dedupeChecking, setDedupeChecking] = useState(false);

  const T = (es, en) => (lang === "es" ? es : en);

  // ── Search profiles con debounce ─────────────────────────────────────────
  useEffect(() => {
    if (mode !== "search") return;
    if (!search || search.trim().length < 2) { setSearchResults([]); return; }
    const id = setTimeout(async () => {
      setSearching(true);
      try {
        const fd = new FormData();
        fd.append("q", search.trim());
        const res = await sbSearchProfiles(fd);
        setSearchResults(res?.ok ? (res.data?.results ?? []) : []);
      } catch { setSearchResults([]); }
      finally { setSearching(false); }
    }, 250);
    return () => clearTimeout(id);
  }, [search, mode]);

  const pickProfile = (p) => {
    setSelectedUserId(p.id);
    setCustomerName([p.first_name, p.last_name].filter(Boolean).join(" ") || p.email || "");
    setCustomerEmail(p.email || "");
    setCustomerPhone(p.phone || "");
    setCustomerWhatsapp(p.phone || "");
    setMode("locked");
    setSearchResults([]);
  };

  const createNew = async () => {
    setError("");
    if (!customerName.trim()) { setError(T("Nombre requerido", "Name required")); return; }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(customerEmail.trim())) { setError(T("Email inválido", "Invalid email")); return; }
    const [firstName, ...rest] = customerName.trim().split(/\s+/);
    const fd = new FormData();
    fd.append("email", customerEmail.trim().toLowerCase());
    if (firstName) fd.append("firstName", firstName);
    if (rest.length) fd.append("lastName", rest.join(" "));
    if (customerPhone.trim()) fd.append("phone", customerPhone.trim());
    const res = await sbCreateCustomerForInvoice(fd);
    if (!res?.ok) { setError(res.error || "Error"); return; }
    setSelectedUserId(res.data.userId);
    if (res.data.isNew) setNewCustomerPwd(res.data.password);
    setMode("locked");
  };

  const resetCustomer = () => {
    setMode("search");
    setSelectedUserId(null);
    setCustomerName("");
    setCustomerEmail("");
    setCustomerPhone("");
    setCustomerWhatsapp("");
    setNewCustomerPwd(null);
    setSearch("");
    setSearchResults([]);
    setDuplicateMatches([]);
  };

  // ── Línea: import desde catálogo ─────────────────────────────────────────
  // Listas combinadas con tipo para el dropdown. Filtramos a published/active.
  // PM 2026-06-17: el price del transfer venía hardcoded en 0 — al importar
  // dejaba el unitPrice vacío y el admin tenía que escribirlo a mano. Ahora
  // usa r.price (tarifa base de la ruta del catálogo). Sigue editable.
  const catalogOptions = useMemo(() => {
    const tours = (TOURS || []).filter(t => !t.status || t.status === "published").map(t => ({
      kind: "tour", id: t.dbId, label: `Tour · ${t.name}`, price: t.price, desc: t.desc,
      // PM 2026-06-24: metadata para calculadora de línea (per_person × pax,
      // per_hour × min). Tours no tienen vehículo ni km.
      pricingUnit: t.pricingUnit || "per_person",
      durationMinutes: (() => {
        // tours.duration_minutes vino desde DB pero el mapper lo convierte a
        // "6 hours" string. Reconstruimos minutos parseando.
        const m = String(t.duration || "").match(/(\d+)\s*hour/);
        if (m) return parseInt(m[1], 10) * 60;
        const min = String(t.duration || "").match(/(\d+)\s*min/);
        return min ? parseInt(min[1], 10) : 60;
      })(),
      maxPax: t.capacity || null,
      titleClean: t.name,
    }));
    const stays = (HOTELS || []).filter(h => !h.status || h.status === "published").map(h => ({
      kind: "stay", id: h.dbId, label: `Stay · ${h.name}`, price: h.price, desc: h.desc,
      // PM 2026-06-24: per_night se modela como per_unit en la calc (la noche
      // entra como "quantity"). per_person aplica si se cobra por persona.
      pricingUnit: h.pricingUnit === "per_night" ? "per_unit" : (h.pricingUnit || "per_unit"),
      durationMinutes: 60,
      maxPax: h.sleeps || null,
      titleClean: h.name,
    }));
    const routes = (ROUTES || []).filter(r => r.active !== false).map(r => ({
      kind: "transfer", id: r.id, label: `Transfer · ${r.from} → ${r.to}`,
      price: Number(r.price) || 0,
      desc: "",
      // PM 2026-06-24 (calc invoice): metadata necesaria para la calculadora
      // de transfer en cada línea (per_person × pax, per_hour × min, vehicle).
      pricingUnit: r.pricingUnit || "per_unit",
      pricingMode: r.pricingMode || "route_price",
      durationMinutes: r.durationMinutes ?? null,
      distanceKm: r.distanceKm ?? null,
      vehicleId: r.vehicleId || null,
      maxPax: r.maxPax || null,
      from: r.from,
      to: r.to,
    }));
    return [...tours, ...stays, ...routes];
  }, []);

  const updateItem = (idx, patch) => {
    setItems((arr) => arr.map((it, i) => (i === idx ? { ...it, ...patch } : it)));
  };
  const addItem = () => setItems((arr) => [...arr, { description: "", quantity: 1, unitPrice: "" }]);
  const removeItem = (idx) => setItems((arr) => (arr.length <= 1 ? arr : arr.filter((_, i) => i !== idx)));

  const importFromCatalog = (idx, optKey) => {
    if (!optKey) {
      // Resetear FK pero conservar texto manual.
      updateItem(idx, { tourId: null, stayId: null, transferRouteId: null, __calc: null });
      return;
    }
    const [kind, id] = optKey.split(":");
    const opt = catalogOptions.find(o => o.kind === kind && o.id === id);
    if (!opt) return;
    // PM 2026-06-24: __calc para los 3 tipos. La calculadora aparece siempre
    // que se importa del catálogo y permite ajustar unidad (per_unit/per_person/
    // per_hour). Para transfer adicionalmente: pricing_mode + vehículo + km.
    // Para tour/stay solo aplican pax y minutos (sin vehículo).
    const calc = {
      open: false,
      kind, // "transfer" | "tour" | "stay"
      pricingUnit: opt.pricingUnit || "per_unit",
      pricingMode: opt.pricingMode || "route_price", // solo relevante para transfer
      pax: 1,
      minutes: opt.durationMinutes || 60,
      km: opt.distanceKm || 0,
      vehicleId: opt.vehicleId || null,
      basePrice: Number(opt.price) || 0,
      maxPax: opt.maxPax || null,
      labelFromTo: opt.from && opt.to
        ? `${opt.from} → ${opt.to}`
        : (opt.titleClean || ""),
    };
    updateItem(idx, {
      description: opt.label.replace(/^(Tour|Stay|Transfer) · /, "") + (opt.desc ? ` — ${opt.desc.slice(0, 80)}` : ""),
      unitPrice: opt.price ? String(opt.price) : "",
      tourId: kind === "tour" ? id : null,
      stayId: kind === "stay" ? id : null,
      transferRouteId: kind === "transfer" ? id : null,
      __calc: calc,
    });
  };

  const subtotal = items.reduce((s, it) => {
    const q = Number(it.quantity) || 0;
    const u = Number(it.unitPrice) || 0;
    return s + q * u;
  }, 0);

  // PM 2026-06-24: helper unificado de la calculadora. Resuelve el precio
  // unitario respetando pricing_unit (per_person × pax, per_hour × hrs).
  // Para kind="transfer" también considera pricing_mode + vehículo. Para
  // kind="tour"/"stay" el modo de precio se ignora (siempre precio base).
  // Devuelve { unit, descSuffix, explain } para que el admin vea el
  // breakdown antes de aplicar.
  const computeTransferLineCalc = (calc) => {
    if (!calc) return { unit: 0, descSuffix: "", explain: "" };
    const isTransfer = (calc.kind || "transfer") === "transfer";
    const veh = isTransfer ? (VEHICLES.find(v => v.id === calc.vehicleId) || null) : null;
    const km = Number(calc.km) || 0;
    const minutes = Number(calc.minutes) || 0;
    const pax = Math.max(1, Number(calc.pax) || 1);
    const base = Number(calc.basePrice) || 0;
    const vehFormula = veh ? ((veh.base || 0) + (veh.perKm || 0) * km) : 0;

    // Precio base según pricing_mode (solo aplica para transfer)
    let routePrice = base;
    let modeExplain = `$${base}`;
    if (isTransfer) {
      const mode = calc.pricingMode || "route_price";
      if (mode === "route_plus_vehicle") {
        routePrice = base + vehFormula;
        modeExplain = veh
          ? `$${base} + (${veh.base || 0} + ${veh.perKm || 0}×${km}km) = $${routePrice.toFixed(2)}`
          : `$${base} (sin vehículo)`;
      } else if (mode === "vehicle_formula") {
        routePrice = vehFormula;
        modeExplain = veh
          ? `${veh.base || 0} + ${veh.perKm || 0}×${km}km = $${routePrice.toFixed(2)}`
          : "Sin vehículo seleccionado";
      }
    }

    // Multiplicador por unidad
    const unit = calc.pricingUnit || "per_unit";
    let unitPrice = routePrice;
    let unitExplain = "";
    let descSuffix = "";
    if (unit === "per_person") {
      unitPrice = routePrice * pax;
      unitExplain = `× ${pax} pax`;
      descSuffix = ` × ${pax} pax`;
    } else if (unit === "per_hour") {
      const hours = minutes / 60;
      unitPrice = routePrice * hours;
      unitExplain = `× ${hours.toFixed(2)}h (${minutes} min)`;
      descSuffix = ` × ${minutes} min`;
    }

    if (veh) descSuffix += ` · ${veh.name || veh.id}`;

    return {
      unit: Number(unitPrice.toFixed(2)),
      descSuffix,
      explain: unitExplain ? `${modeExplain} ${unitExplain}` : modeExplain,
    };
  };

  const applyCalcToLine = (idx) => {
    const it = items[idx];
    if (!it?.__calc) return;
    const { unit, descSuffix } = computeTransferLineCalc(it.__calc);
    // Sobrescribimos description con el formato base (origen → destino) + suffix
    // computado. Si el admin ya había editado el texto manualmente, se respeta
    // como prefijo cuando no contiene un "×" previo.
    const baseLabel = it.__calc.labelFromTo || (it.description || "").split(" — ")[0] || it.description;
    const newDesc = `${baseLabel}${descSuffix}`;
    updateItem(idx, {
      description: newDesc,
      unitPrice: String(unit),
      __calc: { ...it.__calc, open: false },
    });
  };

  const updateCalc = (idx, patch) => {
    const it = items[idx];
    if (!it?.__calc) return;
    updateItem(idx, { __calc: { ...it.__calc, ...patch } });
  };

  // ── Dedupe check: corre cuando hay user seleccionado + items con FK ──────
  useEffect(() => {
    if (!selectedUserId) { setDuplicateMatches([]); return; }
    const tourIds = items.map(i => i.tourId).filter(Boolean);
    const stayIds = items.map(i => i.stayId).filter(Boolean);
    const transferRouteIds = items.map(i => i.transferRouteId).filter(Boolean);
    if (tourIds.length + stayIds.length + transferRouteIds.length === 0) {
      setDuplicateMatches([]); return;
    }
    const id = setTimeout(async () => {
      setDedupeChecking(true);
      try {
        const fd = new FormData();
        fd.append("payload", JSON.stringify({ userId: selectedUserId, tourIds, stayIds, transferRouteIds }));
        const res = await sbFindRecentDuplicates(fd);
        setDuplicateMatches(res?.ok ? (res.data?.matches ?? []) : []);
      } catch { setDuplicateMatches([]); }
      finally { setDedupeChecking(false); }
    }, 400);
    return () => clearTimeout(id);
  }, [selectedUserId, items]);

  // PM 2026-06-24: validación pura — no persiste nada. Devuelve true/false
  // y deja el error en estado. Compartida entre "Vista previa" y "Crear".
  const validateInvoice = () => {
    setError("");
    if (!selectedUserId || mode !== "locked") {
      setError(T("Buscá un cliente existente o creá uno nuevo antes de continuar.", "Search an existing customer or create a new one before continuing."));
      return false;
    }
    if (!customerName.trim()) { setError(T("Nombre del cliente requerido", "Customer name required")); return false; }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(customerEmail.trim())) { setError(T("Email del cliente inválido", "Invalid customer email")); return false; }
    if (items.length === 0) { setError(T("Agregá al menos un ítem", "Add at least one item")); return false; }
    for (let i = 0; i < items.length; i++) {
      const it = items[i];
      if (!it.description.trim()) { setError(T(`Descripción requerida en línea ${i + 1}`, `Description required on line ${i + 1}`)); return false; }
      const q = Number(it.quantity);
      if (!Number.isInteger(q) || q < 1) { setError(T(`Cantidad inválida en línea ${i + 1}`, `Invalid quantity on line ${i + 1}`)); return false; }
      const u = Number(it.unitPrice);
      if (!Number.isFinite(u) || u < 0) { setError(T(`Precio inválido en línea ${i + 1}`, `Invalid price on line ${i + 1}`)); return false; }
    }
    return true;
  };

  // Abrir vista previa: solo valida + scrollea hacia arriba para mostrar
  // el overlay. No toca DB ni Stripe.
  const handleOpenPreview = () => {
    if (!validateInvoice()) return;
    setShowPreview(true);
  };

  // Confirmar desde el preview: AHORA sí persiste. La invoice nace en
  // 'draft' y pasa a 'pending' en el server action; el link de Stripe
  // se genera después manualmente desde la lista de facturas.
  const handleConfirmCreate = async () => {
    setError("");
    const itemsPayload = items.map((it) => ({
      description: it.description.trim(),
      quantity: Number(it.quantity),
      unitCents: Math.round(Number(it.unitPrice) * 100),
      tourId: it.tourId || null,
      stayId: it.stayId || null,
      transferRouteId: it.transferRouteId || null,
    }));

    setSubmitting(true);
    try {
      const fd = new FormData();
      if (selectedUserId) fd.append("userId", selectedUserId);
      fd.append("customerName", customerName.trim());
      fd.append("customerEmail", customerEmail.trim());
      if (customerPhone.trim()) fd.append("customerPhone", customerPhone.trim());
      if (customerWhatsapp.trim()) fd.append("customerWhatsapp", customerWhatsapp.trim());
      if (notes.trim()) fd.append("notes", notes.trim());
      if (dueAt) fd.append("dueAt", dueAt);
      fd.append("paymentMethod", paymentMethod);
      fd.append("items", JSON.stringify(itemsPayload));

      const res = await sbCreateInvoiceManual(fd);
      if (!res?.ok) {
        setError(res?.error || T("Error desconocido", "Unknown error"));
        setSubmitting(false);
        setShowPreview(false); // mostrar el form con el error
        return;
      }
      onCreated(res.data);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
      setSubmitting(false);
      setShowPreview(false);
    }
  };

  return (
    <div className="adm-modal-bg" onClick={onClose}>
      <div className="adm-modal" onClick={(e) => e.stopPropagation()} style={{ maxWidth: 720 }}>
        <button className="adm-modal-close" onClick={onClose}><X /></button>
        <h3>{T("NUEVA FACTURA", "NEW INVOICE")}</h3>
        <p className="adm-modal-sub">{T("Armá la factura y revisá la vista previa antes de crearla. El link de pago se genera después manualmente.", "Build the invoice and review the preview before creating it. The payment link is generated manually afterwards.")}</p>

        <div className="adm-modal-section">
          <div className="adm-modal-section-h">
            <User />{T("Cliente", "Customer")}
            {mode === "locked" && (
              <button type="button" onClick={resetCustomer} style={{ marginLeft: "auto", padding: "4px 10px", borderRadius: 8, background: "transparent", border: "1px solid rgba(255,255,255,.15)", color: "rgba(255,255,255,.7)", fontSize: 10.5, fontWeight: 700, cursor: "pointer", textTransform: "uppercase", letterSpacing: ".08em" }}>
                {T("Cambiar", "Change")}
              </button>
            )}
          </div>

          {mode === "search" && (
            <>
              <div className="adm-fg">
                <label className="adm-fl">{T("Buscar cliente existente (email / nombre / teléfono)", "Search existing customer (email / name / phone)")}</label>
                <input className="adm-fi" value={search} onChange={(e) => setSearch(e.target.value)} placeholder={T("Empezá a tipear…", "Start typing…")} autoFocus />
              </div>
              {(searching || searchResults.length > 0) && (
                <div style={{ marginTop: -6, marginBottom: 10, borderRadius: 10, border: "1px solid rgba(255,255,255,.08)", maxHeight: 200, overflowY: "auto", background: "rgba(0,0,0,.2)" }}>
                  {searching && (
                    <div style={{ padding: "10px 12px", color: "rgba(255,255,255,.5)", fontSize: 12 }}>{T("Buscando…", "Searching…")}</div>
                  )}
                  {!searching && searchResults.length === 0 && search.length >= 2 && (
                    <div style={{ padding: "10px 12px", color: "rgba(255,255,255,.55)", fontSize: 12 }}>{T("Sin resultados", "No matches")}</div>
                  )}
                  {searchResults.map((p) => (
                    <button key={p.id} type="button" onClick={() => pickProfile(p)}
                      style={{ display: "block", width: "100%", textAlign: "left", padding: "10px 12px", background: "transparent", border: "none", borderBottom: "1px solid rgba(255,255,255,.05)", color: "#fff", cursor: "pointer", fontSize: 13 }}>
                      <div style={{ fontWeight: 700 }}>{[p.first_name, p.last_name].filter(Boolean).join(" ") || p.email || "(sin nombre)"}</div>
                      <div style={{ fontSize: 11, color: "rgba(255,255,255,.55)", marginTop: 2 }}>
                        {p.email}{p.phone ? ` · ${p.phone}` : ""}
                      </div>
                    </button>
                  ))}
                </div>
              )}
              <button type="button" className="adm-btn adm-btn-ghost" onClick={() => setMode("create")} style={{ marginTop: 4 }}>
                <Plus />{T("Crear cliente nuevo", "Create new customer")}
              </button>
            </>
          )}

          {mode === "create" && (
            <>
              <p style={{ fontSize: 11.5, color: "rgba(255,255,255,.6)", marginTop: -6, marginBottom: 10 }}>
                {T("Creamos la cuenta con email confirmado. Te devolvemos un password aleatorio que podés enviarle por WhatsApp.", "We create the account with email confirmed. We return a random password you can send via WhatsApp.")}
              </p>
              <div className="adm-fg-row">
                <div className="adm-fg" style={{ flex: 1 }}>
                  <label className="adm-fl">{T("Nombre completo", "Full name")} *</label>
                  <input className="adm-fi" value={customerName} onChange={(e) => setCustomerName(e.target.value)} placeholder="John Smith" />
                </div>
                <div className="adm-fg" style={{ flex: 1 }}>
                  <label className="adm-fl">{T("Email", "Email")} *</label>
                  <input type="email" className="adm-fi" value={customerEmail} onChange={(e) => setCustomerEmail(e.target.value)} placeholder="client@email.com" />
                </div>
              </div>
              <div className="adm-fg">
                <label className="adm-fl">{T("WhatsApp", "WhatsApp")}</label>
                <input className="adm-fi" value={customerPhone} onChange={(e) => setCustomerPhone(e.target.value)} placeholder="+1 787 555 0100" />
              </div>
              <div style={{ display: "flex", gap: 8, marginTop: 4 }}>
                <button type="button" className="adm-btn adm-btn-ghost" onClick={() => { setMode("search"); setError(""); }}>{T("Volver a buscar", "Back to search")}</button>
                <button type="button" className="adm-btn adm-btn-primary" onClick={createNew}>
                  <CheckCircle />{T("Crear y continuar", "Create and continue")}
                </button>
              </div>
            </>
          )}

          {mode === "locked" && (
            <>
              {newCustomerPwd && (
                <div style={{ marginBottom: 12, padding: "12px 14px", borderRadius: 10, background: "rgba(141,198,63,.1)", border: "1px solid rgba(141,198,63,.35)" }}>
                  <div style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: ".12em", color: "#8DC63F", textTransform: "uppercase", marginBottom: 6 }}>
                    {T("Cliente creado — password generado", "Customer created — password generated")}
                  </div>
                  <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
                    <code style={{ fontFamily: "monospace", fontSize: 14, padding: "6px 10px", borderRadius: 8, background: "rgba(0,0,0,.4)", color: "#fff", letterSpacing: ".05em" }}>
                      {newCustomerPwd}
                    </code>
                    <button type="button" onClick={() => { navigator.clipboard.writeText(newCustomerPwd); alert(T("Copiado", "Copied")); }}
                      className="adm-btn adm-btn-ghost" style={{ padding: "6px 12px" }}>
                      <Copy />{T("Copiar", "Copy")}
                    </button>
                    <a href={`https://wa.me/${(customerPhone || "").replace(/\D/g, "")}?text=${encodeURIComponent(T(`Hola ${customerName}, tu cuenta en PRDISE está lista. Email: ${customerEmail} · Password: ${newCustomerPwd} · Iniciá sesión en ${typeof window !== "undefined" ? window.location.origin : "https://livinginprdise.com"}/#/login y cambiá tu password.`, `Hi ${customerName}, your PRDISE account is ready. Email: ${customerEmail} · Password: ${newCustomerPwd} · Sign in at ${typeof window !== "undefined" ? window.location.origin : "https://livinginprdise.com"}/#/login and change your password.`))}`}
                      target="_blank" rel="noopener noreferrer" className="adm-btn adm-btn-ghost" style={{ padding: "6px 12px", textDecoration: "none" }}>
                      <MessageCircle />{T("Enviar por WhatsApp", "Send WhatsApp")}
                    </a>
                  </div>
                  <p style={{ fontSize: 10.5, color: "rgba(255,255,255,.5)", marginTop: 8, lineHeight: 1.5 }}>
                    {T("Esta es la única vez que verás este password — guardalo o envialo ahora.", "This is the only time you'll see this password — save or send it now.")}
                  </p>
                </div>
              )}

              <div style={{ padding: "10px 14px", borderRadius: 10, background: "rgba(245,166,35,.06)", border: "1px solid rgba(245,166,35,.18)", marginBottom: 12 }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: "#fff" }}>{customerName || "(sin nombre)"}</div>
                <div style={{ fontSize: 11.5, color: "rgba(255,255,255,.6)", marginTop: 2 }}>
                  {customerEmail}{customerPhone ? ` · ${customerPhone}` : ""}
                </div>
              </div>

              <div className="adm-fg-row">
                <div className="adm-fg" style={{ flex: 1 }}>
                  <label className="adm-fl">{T("Nombre (mostrado en factura)", "Name (shown on invoice)")} *</label>
                  <input className="adm-fi" value={customerName} onChange={(e) => setCustomerName(e.target.value)} />
                </div>
                <div className="adm-fg" style={{ flex: 1 }}>
                  <label className="adm-fl">{T("Email (factura)", "Email (invoice)")} *</label>
                  <input type="email" className="adm-fi" value={customerEmail} onChange={(e) => setCustomerEmail(e.target.value)} />
                </div>
              </div>
              <div className="adm-fg-row">
                <div className="adm-fg" style={{ flex: 1 }}>
                  <label className="adm-fl">{T("Teléfono", "Phone")}</label>
                  <input className="adm-fi" value={customerPhone} onChange={(e) => setCustomerPhone(e.target.value)} />
                </div>
                <div className="adm-fg" style={{ flex: 1 }}>
                  <label className="adm-fl">WhatsApp</label>
                  <input className="adm-fi" value={customerWhatsapp} onChange={(e) => setCustomerWhatsapp(e.target.value)} placeholder={customerPhone || "+1 787 555 0100"} />
                </div>
                <div className="adm-fg" style={{ flex: 1 }}>
                  <label className="adm-fl">{T("Vencimiento", "Due date")}</label>
                  <input type="date" className="adm-fi" value={dueAt} onChange={(e) => setDueAt(e.target.value)} />
                </div>
              </div>
            </>
          )}
        </div>

        {/* Dedupe banner */}
        {duplicateMatches.length > 0 && (
          <div style={{ margin: "10px 0", padding: "12px 14px", borderRadius: 10, background: "rgba(245,166,35,.1)", border: "1px solid rgba(245,166,35,.35)" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
              <AlertTriangle style={{ width: 14, height: 14, color: "var(--gold)" }} />
              <span style={{ fontSize: 12.5, fontWeight: 700, color: "var(--gold)" }}>
                {T(`Atención: ${duplicateMatches.length} factura(s) pendiente(s) con servicios en común.`, `Warning: ${duplicateMatches.length} pending invoice(s) with overlapping services.`)}
              </span>
            </div>
            {duplicateMatches.map((m) => (
              <div key={m.invoiceId} style={{ fontSize: 11.5, color: "rgba(255,255,255,.75)", marginTop: 4 }}>
                <strong>{m.number}</strong> · <span style={{ color: "rgba(255,255,255,.55)" }}>{m.status}</span> · ${(m.totalCents / 100).toFixed(2)} · {new Date(m.createdAt).toLocaleDateString()} — {m.matchedServices.slice(0, 2).join(", ")}{m.matchedServices.length > 2 ? "…" : ""}
              </div>
            ))}
            <p style={{ fontSize: 10.5, color: "rgba(255,255,255,.5)", marginTop: 8, lineHeight: 1.5 }}>
              {T("Confirmá con el cliente si quiere una factura nueva o pagar la pendiente.", "Confirm with the customer if they want a new invoice or pay the pending one.")}
            </p>
          </div>
        )}

        <div className="adm-modal-section">
          <div className="adm-modal-section-h"><FileText />{T("Líneas", "Line items")}<span style={{ marginLeft: "auto", color: "rgba(255,255,255,.4)", fontWeight: 600, letterSpacing: 0, textTransform: "none" }}>{items.length} {items.length === 1 ? T("ítem", "item") : T("ítems", "items")}</span></div>
          {items.map((it, i) => {
            const linkedKey = it.tourId ? `tour:${it.tourId}` : it.stayId ? `stay:${it.stayId}` : it.transferRouteId ? `transfer:${it.transferRouteId}` : "";
            return (
            <div key={i} style={{ padding: "10px 0", borderBottom: i < items.length - 1 ? "1px solid rgba(255,255,255,.06)" : "none" }}>
              {/* Selector de catálogo: pre-puebla descripción y precio si elegís. */}
              <div className="adm-fg" style={{ marginBottom: 8 }}>
                <label className="adm-fl">
                  {T("Importar de catálogo", "Import from catalog")}
                  {linkedKey && (
                    <span style={{ marginLeft: 8, fontSize: 9.5, fontWeight: 800, letterSpacing: ".1em", color: "#8DC63F" }}>
                      ✓ {T("VINCULADO", "LINKED")}
                    </span>
                  )}
                </label>
                <select className="adm-fi" value={linkedKey} onChange={(e) => importFromCatalog(i, e.target.value)}>
                  <option value="">{T("— línea custom (sin vínculo) —", "— custom line (unlinked) —")}</option>
                  {catalogOptions.map((opt) => (
                    <option key={`${opt.kind}:${opt.id}`} value={`${opt.kind}:${opt.id}`}>
                      {opt.label}{opt.price ? ` · $${opt.price}` : ""}
                    </option>
                  ))}
                </select>
              </div>
              <div style={{ display: "flex", alignItems: "flex-end", gap: 8 }}>
                <div className="adm-fg" style={{ flex: 3, marginBottom: 0 }}>
                  <label className="adm-fl">{T("Descripción", "Description")} *</label>
                  <input className="adm-fi" value={it.description} onChange={(e) => updateItem(i, { description: e.target.value })} placeholder={T("Estadía Cabo Rojo · 2 noches", "Stay Cabo Rojo · 2 nights")} />
                </div>
                <div className="adm-fg" style={{ flex: 1, marginBottom: 0 }}>
                  <label className="adm-fl">{T("Cant.", "Qty")} *</label>
                  <input type="number" min="1" step="1" className="adm-fi" value={it.quantity} onChange={(e) => updateItem(i, { quantity: e.target.value })} />
                </div>
                <div className="adm-fg" style={{ flex: 1, marginBottom: 0 }}>
                  <label className="adm-fl">{T("Precio (USD)", "Price (USD)")} *</label>
                  <input type="number" min="0" step="0.01" className="adm-fi" value={it.unitPrice} onChange={(e) => updateItem(i, { unitPrice: e.target.value })} placeholder="0.00" />
                </div>
                <button
                  type="button"
                  className="adm-icon-btn"
                  title={T("Quitar", "Remove")}
                  onClick={() => removeItem(i)}
                  disabled={items.length <= 1}
                  style={{ opacity: items.length <= 1 ? 0.3 : 1, marginBottom: 4 }}
                ><Trash2 /></button>
              </div>

              {/* PM 2026-06-24: Calculadora unificada (transfer/tour/stay).
                  Aparece SIEMPRE que la línea está vinculada al catálogo.
                  Override de unidad por línea. Para transfer adicionalmente:
                  modo de precio + vehículo + km. NO toca el shape de
                  invoice_items — materializa todo en description +
                  unit_cents al pulsar "Aplicar al precio". */}
              {(it.transferRouteId || it.tourId || it.stayId) && it.__calc && (() => {
                const calc = it.__calc;
                const isTransfer = (calc.kind || "transfer") === "transfer";
                const calcResult = computeTransferLineCalc(calc);
                const needsPax = calc.pricingUnit === "per_person";
                const needsMinutes = calc.pricingUnit === "per_hour";
                const needsVehicle = isTransfer && (calc.pricingMode === "route_plus_vehicle" || calc.pricingMode === "vehicle_formula");
                return (
                  <div style={{ marginTop: 8, borderRadius: 9, background: "rgba(245,166,35,.05)", border: "1px solid rgba(245,166,35,.18)", overflow: "hidden" }}>
                    <button
                      type="button"
                      onClick={() => updateCalc(i, { open: !calc.open })}
                      style={{
                        width: "100%", textAlign: "left", padding: "8px 11px",
                        background: "transparent", border: "none", cursor: "pointer",
                        color: "#F5A623", fontSize: 11, fontWeight: 700, letterSpacing: ".06em",
                        textTransform: "uppercase", display: "flex", alignItems: "center", gap: 6,
                      }}
                    >
                      <span style={{ display: "inline-block", transform: calc.open ? "rotate(90deg)" : "none", transition: "transform .15s" }}>▸</span>
                      {isTransfer
                        ? T("Calculadora de transfer", "Transfer calculator")
                        : calc.kind === "tour"
                          ? T("Calculadora de tour", "Tour calculator")
                          : T("Calculadora de estadía", "Stay calculator")}
                      <span style={{ marginLeft: "auto", color: "rgba(255,255,255,.55)", fontWeight: 600, letterSpacing: 0, textTransform: "none", fontSize: 11 }}>
                        {calc.pricingUnit === "per_person" ? T("por persona", "per person")
                          : calc.pricingUnit === "per_hour" ? T("por hora", "per hour")
                          : T("precio fijo", "flat price")}
                      </span>
                    </button>
                    {calc.open && (
                      <div style={{ padding: "4px 11px 11px 11px", display: "flex", flexDirection: "column", gap: 10 }}>
                        {/* Override de unidad. El admin puede cambiar la
                            forma de cobro por línea sin tocar el catálogo.
                            "Modo de precio" + selector de vehículo solo
                            aplican a transfers. */}
                        <div style={{ display: "grid", gridTemplateColumns: isTransfer ? "1fr 1fr" : "1fr", gap: 8 }}>
                          <div className="adm-fg" style={{ marginBottom: 0 }}>
                            <label className="adm-fl">{T("Unidad de cobro", "Pricing unit")}</label>
                            <select className="adm-fi"
                              value={calc.pricingUnit}
                              onChange={(e) => updateCalc(i, { pricingUnit: e.target.value })}>
                              <option value="per_unit">{T("Precio fijo", "Flat price")}</option>
                              <option value="per_person">{T("Por persona", "Per person")}</option>
                              <option value="per_hour">{T("Por tiempo (minutos)", "By time (minutes)")}</option>
                            </select>
                          </div>
                          {isTransfer && (
                            <div className="adm-fg" style={{ marginBottom: 0 }}>
                              <label className="adm-fl">{T("Modo de precio", "Pricing mode")}</label>
                              <select className="adm-fi"
                                value={calc.pricingMode}
                                onChange={(e) => updateCalc(i, { pricingMode: e.target.value })}>
                                <option value="route_price">{T("Precio fijo de ruta", "Route fixed price")}</option>
                                <option value="route_plus_vehicle">{T("Ruta + vehículo", "Route + vehicle")}</option>
                                <option value="vehicle_formula">{T("Solo fórmula de vehículo", "Vehicle formula only")}</option>
                              </select>
                            </div>
                          )}
                        </div>
                        {(needsPax || needsMinutes || needsVehicle) && (
                        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(120px, 1fr))", gap: 8 }}>
                          {needsPax && (
                            <div className="adm-fg" style={{ marginBottom: 0 }}>
                              <label className="adm-fl">{T("Pax", "Pax")}{calc.maxPax ? ` (máx ${calc.maxPax})` : ""}</label>
                              <input type="number" min="1" step="1" className="adm-fi"
                                value={calc.pax}
                                onChange={(e) => updateCalc(i, { pax: e.target.value })} />
                            </div>
                          )}
                          {needsMinutes && (
                            <div className="adm-fg" style={{ marginBottom: 0 }}>
                              <label className="adm-fl">{T("Duración (min)", "Duration (min)")}</label>
                              <input type="number" min="0" step="1" className="adm-fi"
                                value={calc.minutes}
                                onChange={(e) => updateCalc(i, { minutes: e.target.value })} />
                            </div>
                          )}
                          {needsVehicle && (
                            <>
                              <div className="adm-fg" style={{ marginBottom: 0 }}>
                                <label className="adm-fl">{T("Vehículo", "Vehicle")}</label>
                                <select className="adm-fi"
                                  value={calc.vehicleId || ""}
                                  onChange={(e) => updateCalc(i, { vehicleId: e.target.value || null })}>
                                  <option value="">— {T("Ninguno", "None")} —</option>
                                  {VEHICLES.map(v => (
                                    <option key={v.id} value={v.id}>
                                      {v.name || v.id}{v.base != null ? ` · base $${v.base}` : ""}{v.perKm != null ? ` · $${v.perKm}/km` : ""}
                                    </option>
                                  ))}
                                </select>
                              </div>
                              <div className="adm-fg" style={{ marginBottom: 0 }}>
                                <label className="adm-fl">{T("Km", "Km")}</label>
                                <input type="number" min="0" step="0.1" className="adm-fi"
                                  value={calc.km}
                                  onChange={(e) => updateCalc(i, { km: e.target.value })} />
                              </div>
                            </>
                          )}
                        </div>
                        )}
                        <div style={{ padding: "8px 10px", borderRadius: 7, background: "rgba(0,0,0,.18)", border: "1px solid rgba(255,255,255,.06)" }}>
                          <div style={{ fontSize: 10.5, color: "rgba(255,255,255,.5)", fontWeight: 700, letterSpacing: ".08em", textTransform: "uppercase", marginBottom: 3 }}>
                            {T("Cálculo", "Calculation")}
                          </div>
                          <div style={{ fontSize: 12, color: "rgba(255,255,255,.78)", fontFamily: "monospace", marginBottom: 5 }}>
                            {calcResult.explain}
                          </div>
                          <div style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
                            <span style={{ fontSize: 10.5, color: "rgba(255,255,255,.5)", fontWeight: 700, letterSpacing: ".08em", textTransform: "uppercase" }}>
                              {T("Precio unitario", "Unit price")}
                            </span>
                            <span style={{ fontSize: 17, fontFamily: "Bebas Neue", color: "#F5A623" }}>
                              ${calcResult.unit.toFixed(2)}
                            </span>
                          </div>
                        </div>
                        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
                          <button
                            type="button"
                            className="adm-btn adm-btn-primary"
                            onClick={() => applyCalcToLine(i)}
                            style={{ padding: "6px 12px", fontSize: 11.5 }}
                          >
                            {T("Aplicar al precio", "Apply to price")}
                          </button>
                          <span style={{ fontSize: 10.5, color: "rgba(255,255,255,.4)", lineHeight: 1.4 }}>
                            {T("Sobrescribe precio unitario y descripción. Editable después.", "Overwrites unit price and description. Editable after.")}
                          </span>
                        </div>
                      </div>
                    )}
                  </div>
                );
              })()}
            </div>
            );
          })}
          <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap", marginTop: 10 }}>
            <button type="button" className="adm-btn adm-btn-ghost" onClick={addItem}>
              <Plus />{T("Agregar línea", "Add line")}
            </button>
            {/* PM 2026-06-17: shortcut para tramos de transfer ad-hoc. Agrega
                una línea pre-poblada con "Transfer · " — el admin completa
                origen → destino y precio. Útil para multi-trip armado por
                WhatsApp donde no toda combinación existe en routes. */}
            <button
              type="button"
              className="adm-btn adm-btn-ghost"
              onClick={() => {
                setItems((arr) => [...arr, {
                  description: "Transfer · ",
                  quantity: 1,
                  unitPrice: "",
                  tourId: null, stayId: null, transferRouteId: null,
                }]);
              }}
              style={{ color: "#29ABE2", borderColor: "rgba(41,171,226,.4)" }}
              title={T("Tramo sin ruta predefinida — completá origen → destino y precio", "Trip without predefined route — fill origin → destination and price")}
            >
              <Plus />{T("Tramo de transfer custom", "Custom transfer leg")}
            </button>
          </div>

          {/* PM 2026-06-17: hint visible cuando hay >1 línea o cuando ya hay
              un transfer importado, para que el admin sepa que multi-trip se
              modela con N líneas (una por tramo). */}
          {(items.length > 1 || items.some(it => it.transferRouteId || (it.description || "").toLowerCase().includes("transfer"))) && (
            <div style={{ marginTop: 10, padding: "10px 12px", borderRadius: 9, background: "rgba(41,171,226,.06)", border: "1px solid rgba(41,171,226,.2)", display: "flex", alignItems: "flex-start", gap: 8 }}>
              <Info style={{ width: 13, height: 13, color: "#29ABE2", flexShrink: 0, marginTop: 2 }} />
              <p style={{ fontSize: 11.5, color: "rgba(255,255,255,.7)", margin: 0, lineHeight: 1.55 }}>
                {T(
                  "Para servicios multi-trip (transfer con varias paradas o días distintos), agregá una línea por cada tramo acordado. Todos los precios son editables.",
                  "For multi-trip services (transfer with multiple stops or different days), add a line per agreed trip. All prices are editable."
                )}
              </p>
            </div>
          )}

          <div style={{ display: "flex", justifyContent: "flex-end", alignItems: "baseline", gap: 12, marginTop: 14, paddingTop: 12, borderTop: "1px solid rgba(255,255,255,.08)" }}>
            <span style={{ fontSize: 11, fontWeight: 700, letterSpacing: ".14em", color: "rgba(255,255,255,.5)", textTransform: "uppercase" }}>Total</span>
            <span style={{ fontSize: 24, fontFamily: "Bebas Neue", color: "#F5A623", letterSpacing: ".02em" }}>${subtotal.toFixed(2)}</span>
          </div>
        </div>

        <div className="adm-modal-section">
          <div className="adm-modal-section-h"><CreditCard />{T("Método de pago", "Payment method")}</div>
          <p style={{ fontSize: 11.5, color: "rgba(255,255,255,.55)", marginTop: -4, marginBottom: 10, lineHeight: 1.5 }}>
            {T(
              "Elegí cómo cobrarás esta factura. El link de pago NO se genera al crear — se genera después cuando estés listo.",
              "Choose how this invoice will be paid. The payment link is NOT generated on creation — generate it later when you're ready."
            )}
          </p>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 10 }}>
            {[
              { id: "stripe", label: "Stripe", desc: T("Tarjeta de crédito", "Credit card"), color: "#635BFF" },
              { id: "paypal", label: "PayPal", desc: T("Cuenta PayPal", "PayPal account"), color: "#0070BA" },
              { id: "off_system", label: T("Fuera del sistema", "Off-system"), desc: T("Efectivo, ATH, transferencia", "Cash, ATH, transfer"), color: "#8DC63F" },
            ].map((m) => {
              const sel = paymentMethod === m.id;
              return (
                <button
                  key={m.id}
                  type="button"
                  onClick={() => setPaymentMethod(m.id)}
                  style={{
                    textAlign: "left", padding: 12, borderRadius: 10, cursor: "pointer",
                    background: sel ? "rgba(245,166,35,.1)" : "rgba(255,255,255,.03)",
                    border: sel ? "1.5px solid rgba(245,166,35,.5)" : "1px solid rgba(255,255,255,.08)",
                  }}
                >
                  <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
                    <div style={{ width: 10, height: 10, borderRadius: 2, background: m.color }} />
                    <span style={{ fontSize: 13, fontWeight: 700, color: "#fff" }}>{m.label}</span>
                  </div>
                  <div style={{ fontSize: 11, color: "rgba(255,255,255,.5)" }}>{m.desc}</div>
                </button>
              );
            })}
          </div>
        </div>

        <div className="adm-modal-section">
          <div className="adm-modal-section-h"><Edit />{T("Notas", "Notes")}</div>
          <textarea className="adm-fi" rows={3} value={notes} onChange={(e) => setNotes(e.target.value)} placeholder={T("Notas internas o instrucciones para el cliente (opcional)", "Internal notes or instructions for the client (optional)")} />
        </div>

        {error && (
          <div style={{ padding: 11, borderRadius: 9, background: "rgba(248,113,113,.1)", border: "1px solid rgba(248,113,113,.3)", color: "#f87171", fontSize: 12.5, marginTop: 14, display: "flex", alignItems: "center", gap: 8 }}>
            <AlertTriangle style={{ width: 14, height: 14, flexShrink: 0 }} />
            <span>{error}</span>
          </div>
        )}

        <div className="adm-modal-actions">
          <button className="adm-btn adm-btn-ghost" onClick={onClose} disabled={submitting}>{T("Cancelar", "Cancel")}</button>
          <button
            className="adm-btn adm-btn-primary"
            onClick={handleOpenPreview}
            disabled={submitting || mode !== "locked"}
            title={mode !== "locked" ? T("Confirmá un cliente primero", "Confirm a customer first") : undefined}
            style={{ opacity: (submitting || mode !== "locked") ? 0.55 : 1, cursor: (submitting || mode !== "locked") ? "not-allowed" : "pointer" }}
          >
            <Eye style={{ width: 14, height: 14 }} />
            {T("Vista previa y crear", "Preview and create")}
          </button>
        </div>

        {/* PM 2026-06-24: Vista previa antes de persistir. Overlay sobre el
            modal. Renderiza el invoice como lo vería el cliente (sin número
            real, sin link de pago — esos se generan al confirmar). El admin
            puede "Volver a editar" o "Confirmar y crear". Hasta aquí NADA
            se escribió en DB ni se llamó a Stripe. */}
        {showPreview && (
          <div className="adm-modal-bg" onClick={() => !submitting && setShowPreview(false)} style={{ zIndex: 60 }}>
            <div className="adm-modal" onClick={(e) => e.stopPropagation()} style={{ maxWidth: 680 }}>
              <button className="adm-modal-close" onClick={() => !submitting && setShowPreview(false)} disabled={submitting}><X /></button>
              <h3>{T("VISTA PREVIA DE LA FACTURA", "INVOICE PREVIEW")}</h3>
              <p className="adm-modal-sub">
                {T(
                  "Esto es como verá el cliente la factura. Aún no se ha creado nada — el link de pago tampoco. Al confirmar se persiste y queda pendiente; el link de Stripe se genera después manualmente.",
                  "This is how the customer will see the invoice. Nothing has been created yet — no payment link either. On confirm it is persisted and marked pending; the Stripe link is generated manually afterwards."
                )}
              </p>

              <div style={{
                padding: 18, borderRadius: 10,
                background: "rgba(255,255,255,.03)",
                border: "1px solid rgba(255,255,255,.08)",
                fontSize: 13, color: "rgba(255,255,255,.85)",
              }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 14, paddingBottom: 12, borderBottom: "1px solid rgba(255,255,255,.08)" }}>
                  <div>
                    <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: ".14em", color: "rgba(255,255,255,.45)", textTransform: "uppercase" }}>
                      {T("Factura (borrador)", "Invoice (draft)")}
                    </div>
                    <div style={{ fontFamily: "Bebas Neue", fontSize: 22, color: "#F5A623", letterSpacing: ".04em", marginTop: 2 }}>
                      INV-{new Date().getFullYear()}-•••
                    </div>
                  </div>
                  <div style={{ textAlign: "right", fontSize: 11.5, color: "rgba(255,255,255,.55)" }}>
                    {dueAt && <div>{T("Vence", "Due")}: {dueAt}</div>}
                    <div style={{ marginTop: 4, fontWeight: 700, color: "#F5A623", textTransform: "uppercase", letterSpacing: ".1em", fontSize: 10.5 }}>
                      {paymentMethod === "stripe" ? "Stripe" : paymentMethod === "paypal" ? "PayPal" : T("Fuera del sistema", "Off-system")}
                    </div>
                  </div>
                </div>

                <div style={{ marginBottom: 14 }}>
                  <div style={{ fontSize: 10.5, fontWeight: 700, letterSpacing: ".12em", color: "rgba(255,255,255,.45)", textTransform: "uppercase", marginBottom: 4 }}>
                    {T("Cliente", "Customer")}
                  </div>
                  <div style={{ fontWeight: 700 }}>{customerName}</div>
                  <div style={{ color: "rgba(255,255,255,.6)", fontSize: 12 }}>{customerEmail}</div>
                  {customerPhone && <div style={{ color: "rgba(255,255,255,.6)", fontSize: 12 }}>{customerPhone}</div>}
                </div>

                <div style={{ marginBottom: 14 }}>
                  <div style={{ fontSize: 10.5, fontWeight: 700, letterSpacing: ".12em", color: "rgba(255,255,255,.45)", textTransform: "uppercase", marginBottom: 6 }}>
                    {T("Detalle", "Details")}
                  </div>
                  {items.map((it, i) => {
                    const q = Number(it.quantity) || 0;
                    const u = Number(it.unitPrice) || 0;
                    const total = q * u;
                    return (
                      <div key={i} style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", padding: "6px 0", borderBottom: i < items.length - 1 ? "1px dotted rgba(255,255,255,.08)" : "none" }}>
                        <div style={{ flex: 1, marginRight: 12 }}>
                          <div>{it.description}</div>
                          <div style={{ fontSize: 11, color: "rgba(255,255,255,.45)" }}>
                            {q} × ${u.toFixed(2)}
                          </div>
                        </div>
                        <div style={{ fontFamily: "Bebas Neue", fontSize: 16, color: "#fff", letterSpacing: ".02em" }}>
                          ${total.toFixed(2)}
                        </div>
                      </div>
                    );
                  })}
                </div>

                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", paddingTop: 12, borderTop: "1px solid rgba(255,255,255,.08)" }}>
                  <span style={{ fontSize: 12, fontWeight: 700, letterSpacing: ".14em", color: "rgba(255,255,255,.5)", textTransform: "uppercase" }}>
                    {T("Total a cobrar", "Amount due")}
                  </span>
                  <span style={{ fontSize: 28, fontFamily: "Bebas Neue", color: "#F5A623", letterSpacing: ".02em" }}>
                    ${subtotal.toFixed(2)}
                  </span>
                </div>

                {notes && (
                  <div style={{ marginTop: 14, padding: "10px 12px", borderRadius: 7, background: "rgba(0,0,0,.18)", fontSize: 12, color: "rgba(255,255,255,.7)", lineHeight: 1.5 }}>
                    <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: ".12em", color: "rgba(255,255,255,.45)", textTransform: "uppercase", marginBottom: 3 }}>
                      {T("Notas", "Notes")}
                    </div>
                    {notes}
                  </div>
                )}
              </div>

              {error && (
                <div style={{ padding: 11, borderRadius: 9, background: "rgba(248,113,113,.1)", border: "1px solid rgba(248,113,113,.3)", color: "#f87171", fontSize: 12.5, marginTop: 14, display: "flex", alignItems: "center", gap: 8 }}>
                  <AlertTriangle style={{ width: 14, height: 14, flexShrink: 0 }} />
                  <span>{error}</span>
                </div>
              )}

              <div className="adm-modal-actions">
                <button className="adm-btn adm-btn-ghost" onClick={() => setShowPreview(false)} disabled={submitting}>
                  {T("Volver a editar", "Back to edit")}
                </button>
                <button
                  className="adm-btn adm-btn-primary"
                  onClick={handleConfirmCreate}
                  disabled={submitting}
                  style={{ opacity: submitting ? 0.55 : 1, cursor: submitting ? "not-allowed" : "pointer" }}
                >
                  {submitting ? <Loader2 style={{ width: 14, height: 14, animation: "spin 1s linear infinite" }} /> : <Check />}
                  {submitting ? T("Creando...", "Creating...") : T("Confirmar y crear factura", "Confirm and create invoice")}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}



/* ═══════════════ POST DETAIL PAGE ═══════════════ */
/* ═══════════════ BLOG ARCHIVE PAGE ═══════════════ */
function BlogArchive() {
  const { t, lang } = useLang();
  const L = (en, es) => (lang === "es" && es) ? es : en;
  const [view, setView] = useState("grid");
  const [filter, setFilter] = useState("all");
  const published = A_POSTS.filter(p => p.status === "published");
  const categories = [...new Set(published.map(p => p.category))];
  const filtered = filter === "all" ? published : published.filter(p => p.category === filter);
  const IMG_MAP = { IMG_MANGROVES, IMG_VAN_ROAD, IMG_SUNSET_JETSKI, IMG_AERIAL_BAY, IMG_PALM, IMG_LIGHTHOUSE, IMG_ZIPLINE };
  // PM 2026-06-26: colores desde POST_CATEGORIES dinámico. Si el slug no
  // está en DB (categoría legacy o desactivada) usa fallback hardcoded.
  const FALLBACK_CAT_COLORS = { "Season": "#F5A623", "Travel Advisory": "#29ABE2", "Local Event": "#8DC63F", "Tips": "#EF6C2B", "Guide": "#B794F4", "Food": "#F687B3", "Culture": "#4FD1C5" };
  const CAT_COLORS = new Proxy({}, { get: (_, slug) => (POST_CATEGORIES.find(c => c.slug === slug)?.color) || FALLBACK_CAT_COLORS[slug] || "#F5A623" });

  return (
    <>
      <PageHero tag={lang === "es" ? "Blog" : "Blog"} title={lang === "es" ? "TODOS LOS" : "ALL"} titleEm={lang === "es" ? "ARTÍCULOS" : "ARTICLES"} subtitle={lang === "es" ? "Guías, consejos y noticias sobre la costa oeste de Puerto Rico." : "Guides, tips, and news about Puerto Rico's west coast."} />
      <div className="inner-page">
        <div className="inner-wrap">
          {/* Filter + View Toggle */}
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 28, flexWrap: "wrap", gap: 12 }}>
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              <button onClick={() => setFilter("all")} style={{ padding: "7px 16px", borderRadius: 99, fontSize: 12, fontWeight: 700, cursor: "pointer", transition: "all .2s", background: filter === "all" ? "var(--gold)" : "rgba(255,255,255,.06)", border: filter === "all" ? "none" : "1px solid rgba(255,255,255,.1)", color: filter === "all" ? "#0c1318" : "rgba(255,255,255,.6)" }}>
                {lang === "es" ? "Todos" : "All"} ({published.length})
              </button>
              {categories.map(c => (
                <button key={c} onClick={() => setFilter(c)} style={{ padding: "7px 16px", borderRadius: 99, fontSize: 12, fontWeight: 700, cursor: "pointer", transition: "all .2s", background: filter === c ? (CAT_COLORS[c] || "#F5A623") + "22" : "rgba(255,255,255,.06)", border: `1px solid ${filter === c ? (CAT_COLORS[c] || "#F5A623") + "66" : "rgba(255,255,255,.1)"}`, color: filter === c ? (CAT_COLORS[c] || "#F5A623") : "rgba(255,255,255,.6)" }}>
                  {c}
                </button>
              ))}
            </div>
            <div style={{ display: "flex", gap: 4, padding: 3, borderRadius: 10, background: "rgba(255,255,255,.04)", border: "1px solid rgba(255,255,255,.08)" }}>
              <button onClick={() => setView("grid")} style={{ padding: "6px 10px", borderRadius: 8, background: view === "grid" ? "rgba(245,166,35,.15)" : "transparent", border: "none", color: view === "grid" ? "var(--gold)" : "rgba(255,255,255,.4)", cursor: "pointer", display: "flex" }}>
                <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><rect x="1" y="1" width="6" height="6" rx="1.5" stroke="currentColor" strokeWidth="1.5"/><rect x="9" y="1" width="6" height="6" rx="1.5" stroke="currentColor" strokeWidth="1.5"/><rect x="1" y="9" width="6" height="6" rx="1.5" stroke="currentColor" strokeWidth="1.5"/><rect x="9" y="9" width="6" height="6" rx="1.5" stroke="currentColor" strokeWidth="1.5"/></svg>
              </button>
              <button onClick={() => setView("list")} style={{ padding: "6px 10px", borderRadius: 8, background: view === "list" ? "rgba(245,166,35,.15)" : "transparent", border: "none", color: view === "list" ? "var(--gold)" : "rgba(255,255,255,.4)", cursor: "pointer", display: "flex" }}>
                <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><rect x="1" y="2" width="14" height="3" rx="1" stroke="currentColor" strokeWidth="1.5"/><rect x="1" y="7" width="14" height="3" rx="1" stroke="currentColor" strokeWidth="1.5"/><rect x="1" y="12" width="14" height="3" rx="1" stroke="currentColor" strokeWidth="1.5"/></svg>
              </button>
            </div>
          </div>

          {/* Grid View */}
          {view === "grid" && (
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(300px, 1fr))", gap: 24 }}>
              {filtered.map(p => {
                const img = IMG_MAP[p.img] || IMG_AERIAL_BAY;
                const catColor = CAT_COLORS[p.category] || "#F5A623";
                return (
                  <article key={p.id} onClick={() => nav(`/post?slug=${p.slug}`)} style={{ borderRadius: 18, overflow: "hidden", cursor: "pointer", background: "rgba(255,255,255,.03)", border: "1px solid rgba(255,255,255,.06)", transition: "all .3s" }}
                    onMouseEnter={(e) => { e.currentTarget.style.transform = "translateY(-4px)"; e.currentTarget.style.borderColor = "rgba(245,166,35,.2)"; }}
                    onMouseLeave={(e) => { e.currentTarget.style.transform = ""; e.currentTarget.style.borderColor = "rgba(255,255,255,.06)"; }}
                  >
                    <div style={{ height: 180, overflow: "hidden", position: "relative" }}>
                      <img src={img} alt={p.title} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                      <span style={{ position: "absolute", top: 12, left: 12, fontSize: 9, fontWeight: 800, letterSpacing: ".12em", textTransform: "uppercase", padding: "4px 10px", borderRadius: 99, background: catColor, color: "#0c1318" }}>{p.category}</span>
                      {p.featured && <span style={{ position: "absolute", top: 12, right: 12, fontSize: 9, fontWeight: 800, padding: "4px 8px", borderRadius: 99, background: "linear-gradient(135deg,var(--gold),var(--orange))", color: "#fff" }}>★</span>}
                    </div>
                    <div style={{ padding: "16px 20px 20px" }}>
                      <div style={{ fontSize: 11, color: "rgba(255,255,255,.4)", marginBottom: 6 }}>{p.date} · {p.author}</div>
                      <h3 style={{ fontFamily: "Bebas Neue", fontSize: 20, letterSpacing: ".03em", marginBottom: 8, lineHeight: 1.2 }}>{L(p.title, p.titleES)}</h3>
                      <p style={{ fontSize: 13, color: "rgba(255,255,255,.55)", lineHeight: 1.6, marginBottom: 12, display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical", overflow: "hidden" }}>{L(p.excerpt, p.excerptES)}</p>
                      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                        <span style={{ fontSize: 11, color: "rgba(255,255,255,.35)", display: "flex", alignItems: "center", gap: 4 }}><Eye style={{ width: 11, height: 11 }} />{p.views.toLocaleString()}</span>
                        <span style={{ fontSize: 11, fontWeight: 700, color: "var(--gold)", display: "flex", alignItems: "center", gap: 4 }}>{lang === "es" ? "Leer más" : "Read more"} <ArrowRight style={{ width: 10, height: 10 }} /></span>
                      </div>
                    </div>
                  </article>
                );
              })}
            </div>
          )}

          {/* List View */}
          {view === "list" && (
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              {filtered.map(p => {
                const img = IMG_MAP[p.img] || IMG_AERIAL_BAY;
                const catColor = CAT_COLORS[p.category] || "#F5A623";
                return (
                  <article key={p.id} onClick={() => nav(`/post?slug=${p.slug}`)} style={{ display: "flex", gap: 20, padding: 16, borderRadius: 14, cursor: "pointer", background: "rgba(255,255,255,.03)", border: "1px solid rgba(255,255,255,.06)", transition: "all .25s", alignItems: "center" }}
                    onMouseEnter={(e) => { e.currentTarget.style.borderColor = "rgba(245,166,35,.2)"; e.currentTarget.style.background = "rgba(255,255,255,.05)"; }}
                    onMouseLeave={(e) => { e.currentTarget.style.borderColor = "rgba(255,255,255,.06)"; e.currentTarget.style.background = "rgba(255,255,255,.03)"; }}
                  >
                    <div style={{ width: 120, height: 80, borderRadius: 10, overflow: "hidden", flexShrink: 0 }}>
                      <img src={img} alt={p.title} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                    </div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
                        <span style={{ fontSize: 9, fontWeight: 800, letterSpacing: ".1em", textTransform: "uppercase", padding: "3px 8px", borderRadius: 99, background: catColor + "22", color: catColor }}>{p.category}</span>
                        <span style={{ fontSize: 11, color: "rgba(255,255,255,.35)" }}>{p.date}</span>
                        <span style={{ fontSize: 11, color: "rgba(255,255,255,.35)" }}>· {p.author}</span>
                      </div>
                      <h3 style={{ fontFamily: "Bebas Neue", fontSize: 18, letterSpacing: ".03em", margin: "0 0 4px", lineHeight: 1.2, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{L(p.title, p.titleES)}</h3>
                      <p style={{ fontSize: 12, color: "rgba(255,255,255,.5)", lineHeight: 1.5, margin: 0, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{L(p.excerpt, p.excerptES)}</p>
                    </div>
                    <div style={{ display: "flex", alignItems: "center", gap: 12, flexShrink: 0 }}>
                      <span style={{ fontSize: 11, color: "rgba(255,255,255,.35)", display: "flex", alignItems: "center", gap: 4 }}><Eye style={{ width: 11, height: 11 }} />{p.views.toLocaleString()}</span>
                      <ArrowRight style={{ width: 14, height: 14, color: "var(--gold)" }} />
                    </div>
                  </article>
                );
              })}
            </div>
          )}

          {filtered.length === 0 && (
            <div style={{ textAlign: "center", padding: "60px 20px", color: "rgba(255,255,255,.4)" }}>
              <Edit style={{ width: 40, height: 40, marginBottom: 12, opacity: .3 }} />
              <p>{lang === "es" ? "No hay artículos en esta categoría." : "No articles in this category."}</p>
            </div>
          )}
        </div>
      </div>
    </>
  );
}

function PostDetail({ params }) {
  const { t, lang } = useLang();
  const L = (en, es) => (lang === "es" && es) ? es : en;
  const slug = params.get("slug") || params.get("id") || "";
  const post = A_POSTS.find(p => p.slug === slug || p.id === slug);

  if (!post) return (
    <div className="inner-page"><div className="inner-wrap" style={{ textAlign: "center", padding: "80px 20px" }}>
      <h2 style={{ fontFamily: "Bebas Neue", fontSize: 28 }}>POST NOT FOUND</h2>
      <p style={{ color: "rgba(255,255,255,.5)", marginBottom: 20 }}>The article you're looking for doesn't exist or has been removed.</p>
      <NavLink to="/blog" className="cta-sec">← {lang === "es" ? "Volver al Blog" : "Back to Blog"}</NavLink>
    </div></div>
  );

  const IMG_MAP = { IMG_MANGROVES, IMG_VAN_ROAD, IMG_SUNSET_JETSKI, IMG_AERIAL_BAY, IMG_PALM, IMG_LIGHTHOUSE, IMG_ZIPLINE };
  const coverImg = IMG_MAP[post.img] || IMG_AERIAL_BAY;
  // PM 2026-06-26: colores desde POST_CATEGORIES dinámico. Si el slug no
  // está en DB (categoría legacy o desactivada) usa fallback hardcoded.
  const FALLBACK_CAT_COLORS = { "Season": "#F5A623", "Travel Advisory": "#29ABE2", "Local Event": "#8DC63F", "Tips": "#EF6C2B", "Guide": "#B794F4", "Food": "#F687B3", "Culture": "#4FD1C5" };
  const CAT_COLORS = new Proxy({}, { get: (_, slug) => (POST_CATEGORIES.find(c => c.slug === slug)?.color) || FALLBACK_CAT_COLORS[slug] || "#F5A623" });
  const catColor = CAT_COLORS[post.category] || "#F5A623";

  return (
    <>
      {/* Hero Banner */}
      <div style={{ position: "relative", height: "clamp(280px, 40vh, 420px)", overflow: "hidden" }}>
        <img src={coverImg} alt={post.title} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        <div style={{ position: "absolute", inset: 0, background: "linear-gradient(180deg,rgba(14,24,36,0) 20%,rgba(14,24,36,.6) 60%,rgba(14,24,36,.97) 100%)" }} />
        <div style={{ position: "absolute", bottom: 0, left: 0, right: 0, padding: "40px clamp(20px,5vw,80px) 36px" }}>
          <div style={{ maxWidth: 800 }}>
            <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 12 }}>
              <span style={{ fontSize: 10, fontWeight: 800, letterSpacing: ".14em", textTransform: "uppercase", padding: "5px 12px", borderRadius: 99, background: catColor, color: "#0c1318" }}>{post.category}</span>
              <span style={{ fontSize: 12, color: "rgba(255,255,255,.5)" }}>{post.date}</span>
              {post.featured && <span style={{ fontSize: 10, fontWeight: 800, letterSpacing: ".12em", padding: "4px 10px", borderRadius: 99, background: "linear-gradient(135deg,var(--gold),var(--orange))", color: "#fff" }}>★ Featured</span>}
            </div>
            <h1 style={{ fontFamily: "Bebas Neue", fontSize: "clamp(2rem,5vw,3rem)", letterSpacing: ".02em", lineHeight: 1.1, marginBottom: 10 }}>{L(post.title, post.titleES)}</h1>
            <div style={{ display: "flex", alignItems: "center", gap: 12, fontSize: 13, color: "rgba(255,255,255,.6)" }}>
              <span>By <strong style={{ color: "#fff" }}>{post.author}</strong></span>
              <span>·</span>
              <span><Eye style={{ width: 12, height: 12, display: "inline", verticalAlign: "-1px", marginRight: 4 }} />{post.views.toLocaleString()} views</span>
            </div>
          </div>
        </div>
      </div>

      {/* Article Body */}
      <div className="inner-page" style={{ paddingTop: 40 }}>
        <div style={{ maxWidth: 800, margin: "0 auto" }}>
          {/* Excerpt as lead paragraph */}
          {(post.excerpt || post.excerptES) && (
            <p style={{ fontSize: 17, color: "rgba(255,255,255,.85)", lineHeight: 1.7, marginBottom: 28, fontStyle: "italic", paddingBottom: 24, borderBottom: "1px solid rgba(255,255,255,.08)" }}>
              {L(post.excerpt, post.excerptES)}
            </p>
          )}

          {/* Body content */}
          {(post.body || post.bodyES) && L(post.body, post.bodyES).split("\n\n").map((paragraph, i) => (
            <p key={i} style={{ fontSize: 15, color: "rgba(255,255,255,.75)", lineHeight: 1.8, marginBottom: 20 }}>
              {paragraph.startsWith("•") ? (
                <span style={{ display: "block", paddingLeft: 16, borderLeft: "3px solid var(--gold)", marginLeft: 4 }}>
                  {paragraph.replace(/^[•\-]\s*/, "")}
                </span>
              ) : paragraph}
            </p>
          ))}

          {/* Share / Back */}
          <div style={{ marginTop: 40, paddingTop: 28, borderTop: "1px solid rgba(255,255,255,.08)", display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 12 }}>
            <NavLink to="/blog" style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 13, color: "var(--gold)", fontWeight: 700, textDecoration: "none" }}>
              <ArrowRight style={{ width: 14, height: 14, transform: "rotate(180deg)" }} /> {lang === "es" ? "Volver al Blog" : "Back to Blog"}
            </NavLink>
            {/* PM 2026-06-22 (B): 4 share buttons funcionales. La URL canonica
                del post es livinginprdise.com/#/post?slug=... — no usamos
                window.location.href crudo por si el visitante llegó vía
                preview/iframe. El title viene del post. */}
            {(() => {
              const shareUrl = (typeof window !== "undefined" ? window.location.origin : "https://livinginprdise.com") + `/#/post?slug=${post.slug}`;
              const shareTitle = post.title || "Living in PRdise";
              const enc = encodeURIComponent;
              const targets = [
                {
                  Icon: Facebook, label: "Facebook", color: "#1877F2",
                  href: `https://www.facebook.com/sharer/sharer.php?u=${enc(shareUrl)}`,
                },
                {
                  Icon: MessageCircle, label: "WhatsApp", color: "#25D366",
                  href: `https://api.whatsapp.com/send?text=${enc(shareTitle + " — " + shareUrl)}`,
                },
                {
                  Icon: Twitter, label: "X / Twitter", color: "#fff",
                  href: `https://twitter.com/intent/tweet?text=${enc(shareTitle)}&url=${enc(shareUrl)}`,
                },
                {
                  Icon: Mail, label: lang === "es" ? "Email" : "Email", color: "#F5A623",
                  href: `mailto:?subject=${enc(shareTitle)}&body=${enc(shareTitle + "\n\n" + shareUrl)}`,
                },
              ];
              const copyLink = async () => {
                try {
                  await navigator.clipboard.writeText(shareUrl);
                  alert(lang === "es" ? "Enlace copiado al portapapeles" : "Link copied to clipboard");
                } catch {
                  alert(lang === "es" ? "No se pudo copiar" : "Could not copy");
                }
              };
              // PM 2026-06-23 (D): Instagram no soporta share-URL como
              // Facebook/Twitter. La práctica estándar es copiar el link
              // al clipboard + sugerir pegarlo en una Story o DM. Si el
              // visitante está en mobile, intentamos abrir la app con el
              // deeplink instagram:// y el clipboard listo igual.
              const shareInstagram = async () => {
                try { await navigator.clipboard.writeText(shareUrl); } catch {}
                alert(lang === "es"
                  ? "Enlace copiado al portapapeles. Abrí Instagram y pegalo en tu Story o en un DM para compartirlo."
                  : "Link copied to clipboard. Open Instagram and paste it into your Story or a DM to share.");
                // Best-effort: intentar abrir la app/web de Instagram.
                window.open("https://www.instagram.com/", "_blank", "noopener,noreferrer");
              };
              return (
                <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
                  <span style={{ fontSize: 11, color: "rgba(255,255,255,.4)", textTransform: "uppercase", letterSpacing: ".1em", fontWeight: 700, lineHeight: "32px" }}>
                    {lang === "es" ? "Compartir:" : "Share:"}
                  </span>
                  {targets.map(({ Icon, label, color, href }) => (
                    <a key={label} href={href} target="_blank" rel="noopener noreferrer" aria-label={label}
                      title={label}
                      style={{ width: 32, height: 32, borderRadius: 8, background: "rgba(255,255,255,.06)", border: "1px solid rgba(255,255,255,.1)", color, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", textDecoration: "none" }}
                    >
                      <Icon style={{ width: 14, height: 14 }} />
                    </a>
                  ))}
                  <button onClick={shareInstagram} aria-label="Instagram"
                    title="Instagram"
                    style={{ width: 32, height: 32, borderRadius: 8, background: "rgba(255,255,255,.06)", border: "1px solid rgba(255,255,255,.1)", color: "#E1306C", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}
                  >
                    <Instagram style={{ width: 14, height: 14 }} />
                  </button>
                  <button onClick={copyLink} aria-label={lang === "es" ? "Copiar enlace" : "Copy link"}
                    title={lang === "es" ? "Copiar enlace" : "Copy link"}
                    style={{ width: 32, height: 32, borderRadius: 8, background: "rgba(255,255,255,.06)", border: "1px solid rgba(255,255,255,.1)", color: "rgba(255,255,255,.7)", cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}
                  >
                    <Link2 style={{ width: 14, height: 14 }} />
                  </button>
                </div>
              );
            })()}
          </div>
        </div>
      </div>
    </>
  );
}

function AdminPanelRoute() {
  // Guard real contra Supabase: NO depende solo de localStorage (que puede tener
  // residual de demo o sesiones expiradas). Verifica auth.users + profiles.role.
  const [auth, setAuth] = useState(undefined);
  useEffect(() => {
    let mounted = true;
    const isAuthorizedRole = (r) => r === "admin" || r === "employee";
    (async () => {
      try {
        const { createClient } = await import("@/lib/supabase/client");
        const sb = createClient();
        const { data: { user } } = await sb.auth.getUser();
        if (!user) {
          try { PRDISE.del("session"); PRDISE.del("adminSession"); PRDISE.del("user"); } catch {}
          if (mounted) { nav("/login"); setAuth(false); }
          return;
        }
        const { data: profile } = await sb.from("profiles").select("role,status").eq("id", user.id).maybeSingle();
        if (!profile || profile.status !== "active" || !isAuthorizedRole(profile.role)) {
          if (mounted) { nav("/"); setAuth(false); }
          return;
        }
        if (mounted) { setAuth(true); document.title = "Admin Panel — Living in PRDISE"; }
      } catch {
        if (mounted) { nav("/login"); setAuth(false); }
      }
    })();

    // Protección bfcache: si el browser restaura la página de un cache (back button),
    // re-validar la sesión y redirigir si no es admin.
    const onPageShow = (e) => {
      if (e.persisted) window.location.replace("/");
    };
    window.addEventListener("pageshow", onPageShow);
    return () => { mounted = false; window.removeEventListener("pageshow", onPageShow); };
  }, []);
  if (auth === undefined) {
    return (
      <div style={{ minHeight: "100vh", background: "var(--deep)", color: "rgba(255,255,255,.7)", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "system-ui, sans-serif", fontSize: 14 }}>
        Verificando sesión…
      </div>
    );
  }
  if (auth !== true) return null;
  const exit = async () => {
    try { await sbSignOut(); } catch {}
    try { PRDISE.del("adminSession"); PRDISE.del("session"); PRDISE.del("user"); } catch {}
    window.location.replace("/");
  };
  return <AdminPanel onClose={exit} />;
}

export default function PrdiseApp() {
  const { path, params } = useHashRoute();
  const [dataReady, setDataReady] = useState(false);
  const [splashMinElapsed, setSplashMinElapsed] = useState(false);
  useEffect(() => {
    let mounted = true;
    loadInitialData().then(() => {
      if (mounted) setDataReady(true);
    });
    return () => { mounted = false; };
  }, []);
  useEffect(() => {
    const t = setTimeout(() => setSplashMinElapsed(true), 3000);
    return () => clearTimeout(t);
  }, []);
  // PM 2026-06-17: sync lang desde profiles.lang_pref al mount + cada login.
  // El admin reportó: "el idioma no persiste, tengo que ajustarlo cada vez
  // que inicio sesión". Causa: useLang sólo leía localStorage. Acá al
  // detectar un user authenticated, leemos su lang_pref del DB y si difiere
  // del local, lo sincronizamos (dispatchEvent que useLang escucha).
  useEffect(() => {
    let cancelled = false;
    let unsub = null;
    (async () => {
      try {
        const { createClient } = await import("@/lib/supabase/client");
        const sb = createClient();
        const sync = async (user) => {
          if (!user || cancelled) return;
          const { data: profile } = await sb
            .from("profiles")
            .select("lang_pref")
            .eq("id", user.id)
            .maybeSingle();
          if (!profile?.lang_pref || cancelled) return;
          const cur = PRDISE.load("lang", "en");
          if (cur !== profile.lang_pref) {
            PRDISE.save("lang", profile.lang_pref);
            window.dispatchEvent(new Event("prdise-lang-change"));
          }
        };
        const { data: { user } } = await sb.auth.getUser();
        await sync(user);
        const { data: { subscription } } = sb.auth.onAuthStateChange((_evt, sess) => {
          if (sess?.user) sync(sess.user);
        });
        unsub = subscription;
      } catch { /* fail silently */ }
    })();
    return () => { cancelled = true; if (unsub) unsub.unsubscribe(); };
  }, []);
  if (!dataReady || !splashMinElapsed) {
    return <WelcomeSplash />;
  }
  let page;
  switch (path) {
    case "/":
    case "/home": page = <HomePage />; break;
    case "/stays":
    case "/accommodations": page = <HotelsList />; break;
    case "/stay":
    case "/hotel-detail": page = <HotelDetail params={params} />; break;
    case "/tours":
    case "/packages": page = <ToursList params={params} />; break;
    case "/tour":
    case "/tour-detail": page = <TourDetail params={params} />; break;
    case "/transfer-search":
    case "/transfers": page = <TransferSearchPage />; break;
    case "/transfer-results": page = <TransferResultsPage />; break;
    case "/post": page = <PostDetail params={params} />; break;
    case "/blog":
    case "/archive":
    case "/news": page = <BlogArchive />; break;
    case "/account": page = <AccountPage />; break;
    case "/services": page = <ServicesPage />; break;
    case "/about": page = <AboutPage />; break;
    case "/contact": page = <ContactPage />; break;
    case "/terms": page = <LegalPage kind="terms" />; break;
    case "/privacy": page = <LegalPage kind="privacy" />; break;
    case "/login":
    case "/admin-login": page = <LoginPage />; break;
    case "/register": page = <RegisterPage />; break;
    case "/forgot-password": page = <ForgotPasswordPage />; break;
    case "/admin": page = <AdminPanelRoute />; break;
    default:
      page = (
        <div style={{ minHeight: "100vh", background: "var(--deep)", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", padding: 20 }}>
          <div style={{ textAlign: "center" }}>
            <h1 style={{ fontFamily: "Bebas Neue", fontSize: 64, letterSpacing: ".04em", color: "var(--gold)", marginBottom: 12 }}>404</h1>
            <p style={{ color: "rgba(255,255,255,.6)", marginBottom: 24 }}>Page not found.</p>
            <NavLink to="/" className="cta-pri"><ArrowLeft style={{ width: 14, height: 14 }} />Back to Home</NavLink>
          </div>
        </div>
      );
  }
  const isAdminRoute = path === "/admin" || path === "/admin-login" || path === "/login" || path === "/register" || path === "/forgot-password";
  return (
    <>
      <GlobalStyles />
      {/* PM 2026-06-17: banner sticky cuando la sesión activa proviene de un
          magic-link (admin generó link de confirmación). El componente se
          self-oculta si la sesión no es magic-link o si el usuario ya
          estableció password en este browser. */}
      <MagicLinkPasswordPrompt />
      {/* PM 2026-06-23: el MaintenanceGate envuelve el árbol normal. Si
          site_maintenance_mode=true y el visitante NO es admin, muestra
          la pantalla y oculta navbar/footer/contenido. */}
      <MaintenanceGate>
        {!isAdminRoute && <Navbar />}
        {page}
        {!isAdminRoute && <Footer />}
      </MaintenanceGate>
    </>
  );
}
